    create("TextLabel", {
        Name = "Glyph",
        Position = UDim2.fromOffset(18, 5),
        Size = UDim2.fromOffset(20, 22),
        BackgroundTransparency = 1,
        Font = theme.StrongFont,
        Text = "⌂",
        TextColor3 = theme.Accent,
        TextSize = 19,
        ZIndex = 22,
    }, self.RestoreButton)
    create("TextLabel", {
