end

__bundleFactories["CustomHub.Features.PlaceholderFeatures"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/PlaceholderFeatures.lua
local PlaceholderFeatures = {}

function PlaceholderFeatures:Initialize(_context)
    -- Placeholder actions remain isolated from the independently managed Main Farm.
    return true
end

function PlaceholderFeatures:Handle(actionId, payload, context)
    local state = context.State

    local messages = {
        ["main.selfCheck"] = "UI action path is connected; no gameplay action was run.",
        ["player.status"] = "Player feature is a placeholder; no character data was read.",
        ["teleport.status"] = "Travel feature is a placeholder; no movement or remote was invoked.",
    }
    local message = messages[actionId]
    if message then
        state:SetStatus(message, "success")
        return true
    end

    return false
end

function PlaceholderFeatures:Cleanup(_context)
    -- No placeholder action owns a background task.
end

return PlaceholderFeatures
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/PlaceholderFeatures.lua
end

__bundleFactories["CustomHub.Features.Farm.QuestService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/QuestService.lua
local QuestService = {}
QuestService.__index = QuestService

local MAX_TRACKED_QUEST_TEXT_LENGTH = 160
local MAX_TRACKED_QUEST_PROGRESS_LENGTH = 32
local MAX_MAIN_QUEST_TITLE_LENGTH = 160

local excludedQuestNames = {
    BartiloQuest = true,
    Trainees = true,
    MarineQuest = true,
    CitizenQuest = true,
}

local function diagnosticScalarRepresentation(value)
    local valueType = typeof(value)
    if type(value) == "string" then
        return string.format("<string length=%d>", #value)
    end

    if value == nil or type(value) == "boolean" then
        return tostring(value)
    end
    if type(value) == "number" then
        return "<number-redacted>"
    end
    return "<" .. tostring(valueType) .. ">"
end

local function usableTrackedQuestText(text, maxLength)
    if type(text) ~= "string" or #text == 0 or #text > maxLength then
        return nil
    end

    local trimmed = text:match("^%s*(.-)%s*$")
    if trimmed == "" then
        return nil
    end
    return trimmed
end

local function singularizeQuestTargetWord(word)
    if #word > 3 and word:sub(-3) == "ies" then
        local stem = word:sub(1, -4)
        local lastStemCharacter = stem:sub(-1)
        if lastStemCharacter ~= "" and not lastStemCharacter:match("[aeiou]") then
            return stem .. "y"
        end
    end

    if #word > 4 and word:sub(-2) == "es" then
        local stem = word:sub(1, -3)
        if stem:sub(-1) == "s" or stem:sub(-1) == "x" or stem:sub(-1) == "z"
            or stem:sub(-2) == "ch" or stem:sub(-2) == "sh"
        then
            return stem
        end
    end

    local ending = word:sub(-2)
    if #word > 2 and word:sub(-1) == "s"
        and ending ~= "ss" and ending ~= "us" and ending ~= "is"
    then
        return word:sub(1, -2)
    end
    return word
end

local function normalizeQuestTargetName(name)
    if type(name) ~= "string" or #name == 0 or #name > MAX_TRACKED_QUEST_TEXT_LENGTH then
        return nil
    end

    local words = {}
    for word in name:lower():gmatch("[%w]+") do
        table.insert(words, word)
    end
    if #words == 0 then
        return nil
    end

    words[#words] = singularizeQuestTargetWord(words[#words])
    return table.concat(words, " ")
end

local function trackedTargetMatches(catalogTarget, trackedTarget, allowFirstSeaVariants)
    if catalogTarget == trackedTarget then
        return true
    end
    if not allowFirstSeaVariants then
        return false
    end

    local normalizedCatalogTarget = normalizeQuestTargetName(catalogTarget)
    local normalizedTrackedTarget = normalizeQuestTargetName(trackedTarget)
    return normalizedCatalogTarget ~= nil
        and normalizedCatalogTarget == normalizedTrackedTarget
end

local function isVisibleGuiObjectWithin(instance, root)
    if not instance or not instance:IsA("GuiObject") then
        return false
    end

    local current = instance
    while current and current ~= root do
        if current:IsA("GuiObject") and not current.Visible then
            return false
        end
        if current:IsA("ScreenGui") and not current.Enabled then
            return false
        end
        current = current.Parent
    end
    return current == root
end

local function parseTrackedQuestProgress(text)
    if type(text) ~= "string" or #text > MAX_TRACKED_QUEST_PROGRESS_LENGTH then
        return nil
    end

    local currentText, totalText = text:match("^%s*(%d+)%s*/%s*(%d+)%s*$")
    if not currentText or not totalText then
        return nil
    end

    local current = tonumber(currentText)
    local total = tonumber(totalText)
    if not current or not total
        or current == math.huge
        or total == math.huge
        or total <= 0
        or current >= total
    then
        return nil
    end
    return current, total
end

local function titleContainsTarget(title, targetName, allowFirstSeaVariants)
    if type(title) ~= "string" or type(targetName) ~= "string" then
        return false
    end

    local titleWords = {}
    for word in title:lower():gmatch("[%w]+") do
        table.insert(titleWords, word)
    end
    local targetWords = {}
    for word in targetName:lower():gmatch("[%w]+") do
        table.insert(targetWords, word)
    end
    if #targetWords == 0 or #targetWords > #titleWords then
        return false
    end

    for startIndex = 1, #titleWords - #targetWords + 1 do
        local matches = true
        for offset, expected in ipairs(targetWords) do
            local actual = titleWords[startIndex + offset - 1]
            local finalWord = offset == #targetWords
            local finalWordMatches = finalWord
                and (actual == expected .. "s"
                    or (allowFirstSeaVariants
                        and trackedTargetMatches(actual, expected, true)))
            if actual ~= expected and not finalWordMatches then
                matches = false
                break
            end
        end
        if matches then
            return true
        end
    end
    return false
end

local function parseMainQuestTitleProgress(title)
    if type(title) ~= "string" then
        return nil
    end
    local currentText, totalText = title:match("%((%d+)%s*/%s*(%d+)%)%s*$")
    local current = tonumber(currentText)
    local total = tonumber(totalText)
    if not current or not total or total <= 0 or current >= total then
        return nil
    end
    return current, total
end

local function findEligibleQuestTarget(
    self,
    guideData,
    targetName,
    progressTotal,
    allowFirstSeaActiveQuest
)
    local level = self:GetPlayerLevel()
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if not level or type(npcList) ~= "table" or type(self.Quests) ~= "table" then
        return nil
    end

    local firstSeaMatches = {}
    -- Selection exclusions do not hide a separately verified active First Sea quest.
    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table"
            and (allowFirstSeaActiveQuest or not excludedQuestNames[npcEntry.InternalQuestName])
            and type(npcEntry.Levels) == "table"
        then
            local questGroup = self.Quests[npcEntry.InternalQuestName]
            if type(questGroup) == "table" then
                for questId, requiredLevel in pairs(npcEntry.Levels) do
                    local numericLevel = tonumber(requiredLevel)
                    local quest = questGroup[questId]
                    if numericLevel and numericLevel >= 0 and numericLevel <= level
                        and type(quest) == "table" and type(quest.Task) == "table"
                    then
                        if allowFirstSeaActiveQuest then
                            for mobName, count in pairs(quest.Task) do
                                local numericCount = tonumber(count)
                                if type(mobName) == "string"
                                    and trackedTargetMatches(mobName, targetName, true)
                                    and numericCount == progressTotal and numericCount > 1
                                then
                                    firstSeaMatches[mobName] = true
                                end
                            end
                        else
                            local mobName, count = next(quest.Task)
                            local numericCount = tonumber(count)
                            if mobName == targetName and numericCount == progressTotal
                                and numericCount > 1
                            then
                                return mobName
                            end
                        end
                    end
                end
            end
        end
    end

    if allowFirstSeaActiveQuest then
        local matchedTarget = nil
        for mobName in pairs(firstSeaMatches) do
            if matchedTarget then
                return nil
            end
            matchedTarget = mobName
        end
        return matchedTarget
    end
    return nil
end

local function findEligibleTargetFromTitle(self, guideData, title, progressTotal)
    local level = self:GetPlayerLevel()
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if not level or type(npcList) ~= "table" or type(self.Quests) ~= "table" then
        return nil, "quest catalog or eligible NPC list is unavailable"
    end

    local bestTarget, bestLength, ambiguous = nil, 0, false
    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table"
            and not excludedQuestNames[npcEntry.InternalQuestName]
            and type(npcEntry.Levels) == "table"
        then
            local questGroup = self.Quests[npcEntry.InternalQuestName]
            if type(questGroup) == "table" then
                for questId, requiredLevel in pairs(npcEntry.Levels) do
                    local numericLevel = tonumber(requiredLevel)
                    local quest = questGroup[questId]
                    if numericLevel and numericLevel >= 0 and numericLevel <= level
                        and type(quest) == "table" and type(quest.Task) == "table"
                    then
                        for mobName, count in pairs(quest.Task) do
                            local numericCount = tonumber(count)
                            if type(mobName) == "string" and numericCount and numericCount > 1
                                and numericCount == progressTotal
                                and titleContainsTarget(title, mobName)
                            then
                                local nameLength = #mobName
                                if nameLength > bestLength then
                                    bestTarget, bestLength, ambiguous = mobName, nameLength, false
                                elseif nameLength == bestLength and bestTarget ~= mobName then
                                    ambiguous = true
                                end
                            end
                        end
                    end
                end
            end
        end
    end

    if ambiguous then
        return nil, "visible quest title matches multiple catalog targets"
    end
    if not bestTarget then
        return nil, "visible quest title does not map to a level-eligible catalog target"
    end
    return bestTarget
end

local function readTrackedQuestTarget(self, guideData, isFirstSea)
    local ok, targetName = pcall(function()
        local compatibility = self.Compatibility
        if not compatibility or type(compatibility.GetPlayerGui) ~= "function" then
            return nil
        end

        local playerGui = compatibility:GetPlayerGui()
        local trackedQuestFrame = playerGui and playerGui:FindFirstChild("TrackedQuestFrame")
        if not trackedQuestFrame or not trackedQuestFrame:IsA("ScreenGui")
            or not trackedQuestFrame.Enabled
        then
            return nil
        end

        local frame = trackedQuestFrame:FindFirstChild("Frame")
        local header = frame and frame:FindFirstChild("header")
        local titleLabel = header and header:FindFirstChild("textLabel")
        local description = frame and frame:FindFirstChild("description")
        local progressLabel = frame and frame:FindFirstChild("progress")
        if isFirstSea
            and (not isVisibleGuiObjectWithin(titleLabel, trackedQuestFrame)
                or not isVisibleGuiObjectWithin(description, trackedQuestFrame)
                or not isVisibleGuiObjectWithin(progressLabel, trackedQuestFrame))
        then
            return nil
        end

        local title = titleLabel and usableTrackedQuestText(
            titleLabel.Text,
            MAX_TRACKED_QUEST_TEXT_LENGTH
        )
        local target = description and usableTrackedQuestText(
            description.Text,
            MAX_TRACKED_QUEST_TEXT_LENGTH
        )
        local progressText = progressLabel and progressLabel.Text
        if not title or not target then
            return nil
        end
        if isFirstSea and not titleContainsTarget(title, target, true) then
            return nil
        end
        local progressCurrent, progressTotal = parseTrackedQuestProgress(progressText)
        if progressCurrent == nil or progressTotal == nil then
            return nil
        end

        return findEligibleQuestTarget(self, guideData, target, progressTotal, isFirstSea == true)
    end)

    if not ok then
        return nil
    end
    return targetName
end

local function visibleDialogueText(label, playerGui)
    local isTextLabel = label and (
        label:IsA("TextLabel")
            or label:IsA("TextButton")
            or label:IsA("TextBox")
    )
    if not isTextLabel or not isVisibleGuiObjectWithin(label, playerGui)
        or type(label.Text) ~= "string"
    then
        return nil
    end

    local text = label.Text:match("^%s*(.-)%s*$")
    if text == "" or #text > 64 then
        return nil
    end
    return text
end

local function hasVisibleQuestGiverDialogue(playerGui, guideData)
    local dialogueGui = playerGui and playerGui:FindFirstChild("DialogueGui")
    local titleFrame = dialogueGui
        and dialogueGui:FindFirstChild("dialogueTitleFrame", true)
    if not titleFrame or not isVisibleGuiObjectWithin(titleFrame, playerGui) then
        return false
    end

    local subtitle = titleFrame and titleFrame:FindFirstChild("subtitle")
    local titleLabel = subtitle and subtitle:FindFirstChild("title")
    local titleText = visibleDialogueText(titleLabel, playerGui)
    if titleText and string.lower(titleText) == "quest giver" then
        return true
    end

    -- Later quest-dialogue pages can replace the generic role title with the
    -- speaker name. Match that label against the live quest catalog instead of
    -- hardcoding any NPC name.
    local speakerLabel = titleFrame:FindFirstChild("name")
    local speakerText = visibleDialogueText(speakerLabel, playerGui)
    local npcList = type(guideData) == "table" and guideData.NPCList or nil
    if type(npcList) ~= "table" then
        return false
    end

    for _, npcEntry in pairs(npcList) do
        local npcName = type(npcEntry) == "table" and npcEntry.NPCName or nil
        if type(npcName) == "string" then
            npcName = npcName:match("^%s*(.-)%s*$")
            local normalizedNpcName = string.lower(npcName)
            if (titleText and string.lower(titleText) == normalizedNpcName)
                or (speakerText and string.lower(speakerText) == normalizedNpcName)
            then
                return true
            end
        end
    end
    return false
end

local function readFirstSeaQuestHud(self, guideData)
    local ok, state, targetName, reason = pcall(function()
        local compatibility = self.Compatibility
        if not compatibility or type(compatibility.GetPlayerGui) ~= "function" then
            return "unknown", nil, "PlayerGui reader is unavailable"
        end

        local playerGui = compatibility:GetPlayerGui()
        local main = playerGui and playerGui:FindFirstChild("Main")
        if not main then
            return "unknown", nil, "PlayerGui.Main is unavailable"
        end
        if main:IsA("ScreenGui") and not main.Enabled then
            if hasVisibleQuestGiverDialogue(playerGui, guideData) then
                return "none", nil,
                    "visible Quest Giver dialogue; StartQuest still requires active-state confirmation"
            end
            return "unknown", nil,
                "PlayerGui.Main ScreenGui is disabled; no visible Quest Giver dialogue was found"
        end

        local questFrame = main:FindFirstChild("Quest")
        if not questFrame or not questFrame:IsA("GuiObject") then
            return "unknown", nil, "PlayerGui.Main.Quest is unavailable"
        end
        if not questFrame.Visible then
            return "none", nil, "PlayerGui.Main.Quest.Visible is false"
        end

        local container = questFrame:FindFirstChild("Container")
        local questTitle = container and container:FindFirstChild("QuestTitle")
        local titleLabel = questTitle and questTitle:FindFirstChild("Title")
        local titleIsText = titleLabel and (
            titleLabel:IsA("TextLabel")
                or titleLabel:IsA("TextButton")
                or titleLabel:IsA("TextBox")
        )
        if not titleIsText or not titleLabel.Visible
            or not container or (container:IsA("GuiObject") and not container.Visible)
            or not questTitle or (questTitle:IsA("GuiObject") and not questTitle.Visible)
        then
            return "active-unknown", nil, "visible quest panel has no visible readable title label"
        end

        local title = usableTrackedQuestText(titleLabel.Text, MAX_MAIN_QUEST_TITLE_LENGTH)
        if not title then
            return "active-unknown", nil, "visible quest panel title is empty or malformed"
        end
        local _, progressTotal = parseMainQuestTitleProgress(title)
        if not progressTotal then
            return "active-unknown", nil, "visible quest title has no valid incomplete current/total progress"
        end
        local mappedTarget, mappingError = findEligibleTargetFromTitle(
            self,
            guideData,
            title,
            progressTotal
        )
        if not mappedTarget then
            return "active-unknown", nil, mappingError
        end
        return "active", mappedTarget,
            "visible Main.Quest title/progress maps to the level-eligible quest catalog"
    end)

    if not ok then
        return "unknown", nil, "First Sea quest HUD read failed safely"
    end
    return state, targetName, reason
end

function QuestService.new(compatibility)
    local quests, guide, loadError = compatibility:GetQuestModules()
    if not quests then
        return nil, loadError
    end
    return setmetatable({
        Compatibility = compatibility,
        Player = compatibility.Player,
        Quests = quests,
        Guide = guide,
    }, QuestService)
end

function QuestService:GetPlayerLevel()
    local data = self.Player and self.Player:FindFirstChild("Data")
    local level = data and data:FindFirstChild("Level")
    return level and tonumber(level.Value)
end

function QuestService:IsQuestGiverDialogueOpen()
    local ok, isOpen = pcall(function()
        local compatibility = self.Compatibility
        if not compatibility or type(compatibility.GetPlayerGui) ~= "function" then
            return false
        end
        local guideData = self.Guide and self.Guide.Data
        return hasVisibleQuestGiverDialogue(compatibility:GetPlayerGui(), guideData)
    end)
    return ok and isOpen == true
end

function QuestService:GetActiveQuestState()
    local guideData = self.Guide and self.Guide.Data
    local questData = type(guideData) == "table" and guideData.QuestData or nil
    if type(questData) == "table" and type(questData.Task) == "table" then
        local targetName = next(questData.Task)
        if type(targetName) == "string" and targetName ~= "" then
            return "active", targetName, "GuideModule.Data.QuestData.Task"
        end
    end

    local firstSea = false
    if self.Compatibility and type(self.Compatibility.IsFirstSea) == "function" then
        local seaReadOk, isFirstSea = pcall(self.Compatibility.IsFirstSea, self.Compatibility)
        firstSea = seaReadOk and isFirstSea == true
    end

    local trackedTarget = readTrackedQuestTarget(self, guideData, firstSea)
    if trackedTarget then
        return "active", trackedTarget, "TrackedQuestFrame title/target/progress mapped to quest catalog"
    end

    if firstSea then
        local hudState, hudTarget, hudReason = readFirstSeaQuestHud(self, guideData)
        return hudState, hudTarget, hudReason
    end

    if type(guideData) ~= "table" then
        return "unknown", nil, "GuideModule.Data is unavailable"
    end
    if questData == nil then
        return "none", nil, "GuideModule.Data.QuestData is absent"
    end
    if type(questData) ~= "table" or type(questData.Task) ~= "table" then
        return "unknown", nil, "GuideModule.Data.QuestData.Task is not a table"
    end
    return "active-unknown", nil, "GuideModule exposes a quest record without a readable task"
end

function QuestService:SelectLevelQuest()
    local level = self:GetPlayerLevel()
    local guideData = self.Guide and self.Guide.Data
    local npcList = guideData and guideData.NPCList
    if not level or type(npcList) ~= "table" then
        return nil, "Player level or GuideModule.Data.NPCList is unavailable"
    end

    local bestLevel = 0
    local bestCandidate = nil
    for _, npcEntry in pairs(npcList) do
        if type(npcEntry) == "table" and not excludedQuestNames[npcEntry.InternalQuestName] then
            local questGroup = self.Quests[npcEntry.InternalQuestName]
            if type(npcEntry.Levels) == "table" and type(questGroup) == "table" then
                for questId, requiredLevel in pairs(npcEntry.Levels) do
                    local quest = questGroup[questId]
                    local numericLevel = tonumber(requiredLevel)
                    if type(quest) == "table"
                        and type(quest.Task) == "table"
                        and numericLevel
                        and numericLevel <= level
                        and numericLevel >= bestLevel
                    then
                        local mobName, count = next(quest.Task)
                        local numericCount = tonumber(count)
                        if type(mobName) == "string" and numericCount and numericCount > 1 then
                            bestCandidate = {
                                Level = numericLevel,
                                Name = npcEntry.NPCName,
                                QuestName = npcEntry.InternalQuestName,
                                Pos = npcEntry.Position,
                                Id = questId,
                                Mob = mobName,
                            }

                            local activeState, activeTarget = self:GetActiveQuestState()
                            local numericQuestId = tonumber(questId)
                            if activeState == "active"
                                and activeTarget == mobName
                                and numericQuestId
                                and numericQuestId > 1
                            then
                                local previousQuest = questGroup[numericQuestId - 1]
                                if previousQuest and type(previousQuest.Task) == "table" then
                                    for previousMob, previousCount in pairs(previousQuest.Task) do
                                        if previousMob ~= activeTarget
                                            and tonumber(previousCount)
                                            and tonumber(previousCount) > 1
                                        then
                                            bestCandidate.Mob = previousMob
                                            bestCandidate.Id = numericQuestId - 1
                                            break
                                        end
                                    end
                                end
                            end
                            bestLevel = numericLevel
                        end
                    end
                end
            end
        end
    end

    if not bestCandidate then
        return nil, "No eligible level-based quest candidate"
    end
    return bestCandidate
end

function QuestService:RequestStart(candidate)
    self.LastStartDiagnostic = {
        Stage = "pcall_not_reached",
        PcallSucceeded = nil,
        ResultType = "n/a",
        ResultSummary = "not returned",
    }
    if type(candidate) ~= "table" or not candidate.QuestName or candidate.Id == nil then
        self.LastStartDiagnostic.Stage = "candidate_invalid"
        return false, "Quest candidate is incomplete"
    end

    local commF, remoteError = self.Compatibility:GetCommF()
    if not commF then
        self.LastStartDiagnostic.Stage = "remote_unavailable"
        return false, remoteError
    end
    local ok, result = pcall(function()
        return commF:InvokeServer("StartQuest", tostring(candidate.QuestName), candidate.Id)
    end)
    pcall(function()
        self.LastStartDiagnostic = {
            Stage = "pcall_completed",
            PcallSucceeded = ok,
            ResultType = tostring(typeof(result)),
            ResultSummary = diagnosticScalarRepresentation(result),
        }
    end)
    if not ok then
        return false, tostring(result)
    end

    -- BNN ignores this return value; acceptance is confirmed separately through QuestData.Task.
    return true, result
end

return QuestService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/QuestService.lua
end

__bundleFactories["CustomHub.Features.Farm.EnemyService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/EnemyService.lua
local EnemyService = {}
EnemyService.__index = EnemyService

local HIDDEN_SPAWN_REFRESH_INTERVAL = 1
local HIDDEN_SPAWN_RETRY_INTERVAL = 5

local function singularizeEnemyWord(word)
    if #word > 3 and word:sub(-3) == "ies" then
        local stem = word:sub(1, -4)
        local lastStemCharacter = stem:sub(-1)
        if lastStemCharacter ~= "" and not lastStemCharacter:match("[aeiou]") then
            return stem .. "y"
        end
    end

    if #word > 4 and word:sub(-2) == "es" then
        local stem = word:sub(1, -3)
        if stem:sub(-1) == "s" or stem:sub(-1) == "x" or stem:sub(-1) == "z"
            or stem:sub(-2) == "ch" or stem:sub(-2) == "sh"
        then
            return stem
        end
    end

    local ending = word:sub(-2)
    if #word > 2 and word:sub(-1) == "s"
        and ending ~= "ss" and ending ~= "us" and ending ~= "is"
    then
        return word:sub(1, -2)
    end
    return word
end

local function normalizeEnemyName(name)
    if type(name) ~= "string" or #name == 0 then
        return nil
    end

    local baseName = name:lower():gsub("%s+%p?lv%.?%s*%d+%p?%s*$", "")
    local words = {}
    for word in baseName:gmatch("[%w]+") do
        table.insert(words, word)
    end
    if #words == 0 then
        return nil
    end

    words[#words] = singularizeEnemyWord(words[#words])
    return table.concat(words, " ")
end

local function matchesEnemyName(enemyName, targetName)
    local normalizedEnemyName = normalizeEnemyName(enemyName)
    if not normalizedEnemyName then
        return false
    end

    if type(targetName) == "string" then
        return normalizedEnemyName == normalizeEnemyName(targetName)
    end
    if type(targetName) == "table" then
        for _, candidateName in ipairs(targetName) do
            if type(candidateName) == "string"
                and normalizedEnemyName == normalizeEnemyName(candidateName)
            then
                return true
            end
        end
    end
    return false
end

local function isDescendantOf(instance, container)
    if not instance or not container then
        return false
    end
    local ok, result = pcall(function()
        return instance:IsDescendantOf(container)
    end)
    return ok and result == true
end

local function matchesSpawnName(spawnName, normalizedTarget)
    return normalizedTarget ~= nil and normalizeEnemyName(spawnName) == normalizedTarget
end

function EnemyService.new(compatibility)
    return setmetatable({
        Compatibility = compatibility,
        Workspace = compatibility.Workspace,
        CollisionOriginals = {},
        IgnoredSpawns = {},
        HiddenSpawnCache = nil,
    }, EnemyService)
end

function EnemyService:_GetEnemySpawnsFolder()
    local worldOrigin = self.Workspace:FindFirstChild("_WorldOrigin")
    if not worldOrigin then
        worldOrigin = self.Workspace:FindFirstChild("_WorldOrigin", true)
    end
    if not worldOrigin then
        return self.Workspace:FindFirstChild("EnemySpawns", true)
    end

    local enemySpawns = worldOrigin:FindFirstChild("EnemySpawns")
    if not enemySpawns then
        enemySpawns = worldOrigin:FindFirstChild("EnemySpawns", true)
    end
    if not enemySpawns then
        enemySpawns = self.Workspace:FindFirstChild("EnemySpawns", true)
    end
    return enemySpawns
end

function EnemyService:_RefreshHiddenSpawnCache()
    local now = os.clock()
    local current = self.HiddenSpawnCache
    if current and now < current.ExpiresAt then
        return current
    end

    local cache = {
        Parts = {},
        Available = false,
        ExpiresAt = now + HIDDEN_SPAWN_RETRY_INTERVAL,
    }
    local getter = self.Compatibility and self.Compatibility.GetUnparentedInstances
    if type(getter) == "function" then
        local callOk, instances = pcall(getter, self.Compatibility)
        if callOk and type(instances) == "table" then
            cache.Available = true
            cache.ExpiresAt = now + HIDDEN_SPAWN_REFRESH_INTERVAL
            local scanOk = pcall(function()
                for _, instance in pairs(instances) do
                    local readOk, isBasePart, name, parent = pcall(function()
                        return instance:IsA("BasePart"), instance.Name, instance.Parent
                    end)
                    if readOk and isBasePart and parent == nil and type(name) == "string" then
                        cache.Parts[instance] = name
                    end
                end
            end)
            if not scanOk then
                cache.Parts = {}
                cache.Available = false
                cache.ExpiresAt = now + HIDDEN_SPAWN_RETRY_INTERVAL
            end
        end
    end

    self.HiddenSpawnCache = cache
    return cache
end

function EnemyService:_PruneIgnoredSpawns(enemySpawns, hiddenCache, targetName)
    local normalizedTarget = normalizeEnemyName(targetName)
    for spawnPart in pairs(self.IgnoredSpawns) do
        local readOk, isBasePart, name, parent = pcall(function()
            return spawnPart:IsA("BasePart"), spawnPart.Name, spawnPart.Parent
        end)
        local matchingName = readOk
            and isBasePart
            and type(name) == "string"
            and matchesSpawnName(name, normalizedTarget)
        local replicated = matchingName
            and enemySpawns ~= nil
            and parent ~= nil
            and isDescendantOf(spawnPart, enemySpawns)
        local hidden = matchingName
            and parent == nil
            and hiddenCache.Available
            and hiddenCache.Parts[spawnPart] == name
        if not replicated and not hidden then
            self.IgnoredSpawns[spawnPart] = nil
        end
    end
end

function EnemyService:IsAlive(model)
    if not model or not model.Parent then
        return false
    end
    local root = model:FindFirstChild("HumanoidRootPart")
    local humanoid = model:FindFirstChildWhichIsA("Humanoid")
    return root ~= nil and humanoid ~= nil and humanoid.Health > 0
end

function EnemyService:FindNearest(targetName, origin)
    local enemies = self.Workspace:FindFirstChild("Enemies")
    if not enemies then
        enemies = self.Workspace:FindFirstChild("Enemies", true)
    end
    if not enemies or not targetName or not origin then
        return nil
    end

    local nearest, nearestDistance = nil, math.huge
    for _, enemy in ipairs(enemies:GetDescendants()) do
        if enemy:IsA("Model")
            and matchesEnemyName(enemy.Name, targetName)
            and self:IsAlive(enemy)
        then
            local distance = (enemy.HumanoidRootPart.Position - origin).Magnitude
            if distance < nearestDistance then
                nearest, nearestDistance = enemy, distance
            end
        end
    end
    return nearest, nearestDistance
end

function EnemyService:FindSpawn(targetName, origin)
    local diagnostic = {
        TargetName = targetName,
        EnemySpawnsContainerFound = false,
        NormalMarkerFound = false,
        HiddenMarkerFound = false,
        HiddenDiscoveryAvailable = false,
        SelectedSource = "none",
        SelectedName = nil,
        SelectedDistance = nil,
    }
    if type(targetName) ~= "string" then
        return nil, false, diagnostic
    end

    local enemySpawns = self:_GetEnemySpawnsFolder()
    local hiddenCache = self:_RefreshHiddenSpawnCache()
    diagnostic.EnemySpawnsContainerFound = enemySpawns ~= nil
    diagnostic.HiddenDiscoveryAvailable = hiddenCache.Available == true
    local normalizedTarget = normalizeEnemyName(targetName)
    self:_PruneIgnoredSpawns(enemySpawns, hiddenCache, targetName)

    local hasMatchingSpawn = false
    local nearest, nearestDistance = nil, math.huge
    local function considerSpawn(spawnPart, expectedParent, expectedName, source)
        local readOk, isBasePart, name, parent, position = pcall(function()
            return spawnPart:IsA("BasePart"), spawnPart.Name, spawnPart.Parent, spawnPart.Position
        end)
        local inExpectedContainer = source == "EnemySpawns"
            and isDescendantOf(spawnPart, expectedParent)
        local inHiddenCache = source == "unparented-cache" and parent == nil
        if not readOk
            or not isBasePart
            or (source == "EnemySpawns" and not inExpectedContainer)
            or (source == "unparented-cache" and not inHiddenCache)
            or type(name) ~= "string"
            or (expectedName and name ~= expectedName)
            or not matchesSpawnName(name, normalizedTarget)
        then
            return
        end

        hasMatchingSpawn = true
        if source == "EnemySpawns" then
            diagnostic.NormalMarkerFound = true
        elseif source == "unparented-cache" then
            diagnostic.HiddenMarkerFound = true
        end
        if self.IgnoredSpawns[spawnPart] then
            return
        end
        local distance = typeof(origin) == "Vector3"
            and (position - origin).Magnitude
            or 0
        if distance < nearestDistance then
            nearest, nearestDistance = spawnPart, distance
            diagnostic.SelectedSource = source
            diagnostic.SelectedName = name
            diagnostic.SelectedDistance = distance
        end
    end

    if enemySpawns then
        local childrenOk, children = pcall(function()
            return enemySpawns:GetDescendants()
        end)
        if childrenOk then
            for _, spawnPart in ipairs(children) do
                considerSpawn(spawnPart, enemySpawns, nil, "EnemySpawns")
            end
        end
    end

    -- Include cached unparented candidates in nearest selection, but refresh the
    -- potentially expensive runtime enumeration no more than once per cache interval.
    if hiddenCache.Available and os.clock() < hiddenCache.ExpiresAt then
        for spawnPart, cachedName in pairs(hiddenCache.Parts) do
            if matchesSpawnName(cachedName, normalizedTarget) then
                considerSpawn(spawnPart, nil, cachedName, "unparented-cache")
            end
        end
    end

    if nearest then
        return nearest, false, diagnostic
    end
    return nil, hasMatchingSpawn, diagnostic
end

function EnemyService:IsSpawnAvailable(spawnPart, targetName)
    if not spawnPart or type(targetName) ~= "string" then
        return false
    end
    local readOk, isBasePart, name, parent = pcall(function()
        return spawnPart:IsA("BasePart"), spawnPart.Name, spawnPart.Parent
    end)
    if not readOk
        or not isBasePart
        or type(name) ~= "string"
        or self.IgnoredSpawns[spawnPart]
    then
        return false
    end

    local normalizedTarget = normalizeEnemyName(targetName)
    if not matchesSpawnName(name, normalizedTarget) then
        return false
    end

    local enemySpawns = self:_GetEnemySpawnsFolder()
    if enemySpawns ~= nil and parent ~= nil and isDescendantOf(spawnPart, enemySpawns) then
        return true
    end

    local hiddenCache = self.HiddenSpawnCache
    return parent == nil
        and hiddenCache ~= nil
        and hiddenCache.Available
        and os.clock() < hiddenCache.ExpiresAt
        and hiddenCache.Parts[spawnPart] == name
end

function EnemyService:MarkSpawnIgnored(spawnPart, targetName)
    if self:IsSpawnAvailable(spawnPart, targetName) then
        self.IgnoredSpawns[spawnPart] = true
    end
end

function EnemyService:ClearIgnoredSpawns()
    table.clear(self.IgnoredSpawns)
end

function EnemyService:PrepareTarget(model, playerRoot)
    if not self:IsAlive(model) or not playerRoot then
        return
    end
    if (model.HumanoidRootPart.Position - playerRoot.Position).Magnitude > 50 then
        return
    end

    for _, part in ipairs(model:GetDescendants()) do
        if part:IsA("BasePart") and part.CanCollide then
            self.CollisionOriginals[part] = true
            part.CanCollide = false
        end
    end
end

function EnemyService:RestoreTargetCollision()
    for part, originalCanCollide in pairs(self.CollisionOriginals) do
        if part and part.Parent then
            part.CanCollide = originalCanCollide
        end
        self.CollisionOriginals[part] = nil
    end
end

return EnemyService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/EnemyService.lua
end

__bundleFactories["CustomHub.Features.Farm.MovementService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/MovementService.lua
local MovementService = {}
MovementService.__index = MovementService

local SUBMERGED_REFERENCE = Vector3.new(11538.599609375, -2154.7021484375, 9827.3125)
local SUBMERGED_STAGING = CFrame.new(
    -16269.4082,
    23.9799957,
    1371.66235,
    -0.999388933,
    0,
    -0.0349550731,
    0,
    1,
    0,
    0.0349550731,
    0,
    -0.999388933
)
local TIKI_STAGING = CFrame.new(
    11427.9189,
    -2156.36401,
    9726.24023,
    -0.929097056,
    -7.17796156E-34,
    0.369835705,
    -7.17796156E-34,
    1,
    1.37611875E-34,
    -0.369835705,
    -1.37611875E-34,
    -0.929097056
)

function MovementService.new(compatibility, report)
    return setmetatable({
        Compatibility = compatibility,
        Report = report,
        Active = nil,
        Generation = 0,
        RouteGeneration = 0,
        TagGeneration = 0,
        OwnsTeleportTag = false,
        LastRouteRequest = {},
        FarmCollisionActive = false,
        FarmCollisionConnection = nil,
        FarmCollisionCharacter = nil,
        FarmCollisionOriginals = {},
        FarmCollisionErrorReported = false,
    }, MovementService)
end

function MovementService:_GetRoute(destination, currentPosition)
    if not self.Compatibility:IsThirdSea() then
        return nil
    end

    local destinationDistance = (destination.Position - SUBMERGED_REFERENCE).Magnitude
    local currentDistance = (currentPosition - SUBMERGED_REFERENCE).Magnitude
    if destinationDistance <= 3000 and currentDistance > 3000 then
        return { Name = "Submerged", Stage = SUBMERGED_STAGING }
    end
    if destinationDistance > 3000 and currentDistance <= 3000 then
        return { Name = "Tiki", Stage = TIKI_STAGING }
    end
    return nil
end

function MovementService:_RestoreCollision(active)
    for part, canCollide in pairs(active.CollisionOriginals) do
        if part and part.Parent then
            part.CanCollide = canCollide
        end
        active.CollisionOriginals[part] = nil
    end
end

function MovementService:_RestoreFarmCollision()
    for part, canCollide in pairs(self.FarmCollisionOriginals) do
        pcall(function()
            if part.Parent then
                part.CanCollide = canCollide
            end
        end)
    end
    table.clear(self.FarmCollisionOriginals)
    self.FarmCollisionCharacter = nil
end

function MovementService:_ApplyFarmCollision()
    if not self.FarmCollisionActive then
        return true
    end

    local player = self.Compatibility.Player
    local character = player and player.Character
    if character ~= self.FarmCollisionCharacter then
        self:_RestoreFarmCollision()
        self.FarmCollisionCharacter = character
    end
    if not character then
        return true
    end

    for _, descendant in ipairs(character:GetDescendants()) do
        if descendant:IsA("BasePart") then
            if self.FarmCollisionOriginals[descendant] == nil then
                self.FarmCollisionOriginals[descendant] = descendant.CanCollide
            end
            descendant.CanCollide = false
        end
    end
    return true
end

function MovementService:SetFarmCollisionSuppression(enabled)
    enabled = enabled == true
    if not enabled then
        self.FarmCollisionActive = false
        local connection = self.FarmCollisionConnection
        self.FarmCollisionConnection = nil
        if connection and connection.Connected then
            connection:Disconnect()
        end
        self:_RestoreFarmCollision()
        self.FarmCollisionErrorReported = false
        return true
    end

    if self.FarmCollisionActive
        and self.FarmCollisionConnection
        and self.FarmCollisionConnection.Connected
    then
        local ok, err = pcall(self._ApplyFarmCollision, self)
        if not ok then
            return false, tostring(err)
        end
        return true
    end

    self.FarmCollisionActive = true
    local ok, err = pcall(self._ApplyFarmCollision, self)
    if not ok then
        self.FarmCollisionActive = false
        self:_RestoreFarmCollision()
        return false, tostring(err)
    end

    local connected, connection = pcall(function()
        return self.Compatibility.RunService.Heartbeat:Connect(function()
            local applyOk, applyError = pcall(self._ApplyFarmCollision, self)
            if applyOk then
                self.FarmCollisionErrorReported = false
            elseif not self.FarmCollisionErrorReported and self.Report then
                self.FarmCollisionErrorReported = true
                self.Report(
                    "Character collision maintenance error: " .. tostring(applyError),
                    "warning"
                )
            end
        end)
    end)
    if not connected or not connection then
        self.FarmCollisionActive = false
        self:_RestoreFarmCollision()
        return false, tostring(connection or "Heartbeat connection is unavailable")
    end
    self.FarmCollisionConnection = connection
    return true
end

function MovementService:_Finish(active, delayTagRemoval)
    if self.Active ~= active then
        return
    end
    self.Active = nil
    if active.Connection and active.Connection.Connected then
        active.Connection:Disconnect()
    end
    self:_RestoreCollision(active)

    if active.FloatForce and active.FloatForce.Parent then
        active.FloatForce:Destroy()
    end
    if active.Humanoid and active.Humanoid.Parent then
        active.Humanoid.PlatformStand = false
    end

    if active.HasTeleportTag then
        local tagGeneration = self.TagGeneration
        local function removeTag()
            if self.Active == nil
                and self.TagGeneration == tagGeneration
                and self.Compatibility.CollectionService:HasTag(self.Compatibility.Player, "Teleporting")
            then
                self.Compatibility.CollectionService:RemoveTag(self.Compatibility.Player, "Teleporting")
                self.OwnsTeleportTag = false
            end
        end
        if delayTagRemoval then
            task.delay(1.5, removeTag)
        else
            removeTag()
        end
    end
end

function MovementService:_StopMovement()
    self.Generation += 1
    local active = self.Active
    if active then
        self:_Finish(active, true)
    end
end

function MovementService:Cancel()
    self.RouteGeneration += 1
    self:_StopMovement()
end

function MovementService:_RequestRoute(route, isCurrent, routeGeneration)
    local now = os.clock()
    if now - (self.LastRouteRequest[route.Name] or 0) < 5 then
        return false, "Travel request is cooling down"
    end
    self.LastRouteRequest[route.Name] = now

    task.spawn(function()
        if not isCurrent() or self.RouteGeneration ~= routeGeneration then
            return
        end
        local replication = self.Compatibility.ReplicatedStorage
        local modules = replication:FindFirstChild("Modules")
        local netContainer = modules and modules:FindFirstChild("Net")
        local commF, commFError = self.Compatibility:GetCommF()
        if not netContainer or not commF then
            self.Report("Travel dependencies are unavailable", "error")
            return
        end

        local ok, err = pcall(function()
            if route.Name == "Submerged" then
                local remote = netContainer:FindFirstChild("RF/SubmarineWorkerSpeak")
                if not remote then
                    error("Modules.Net.RF/SubmarineWorkerSpeak is unavailable")
                end
                remote:InvokeServer("TravelToSubmergedIsland")
                if isCurrent() and self.RouteGeneration == routeGeneration then
                    commF:InvokeServer("SetLastSpawnPoint", "SubmergedIsland")
                end
            else
                local remote = netContainer:FindFirstChild("RF/SubmarineTransportation")
                if not remote then
                    error("Modules.Net.RF/SubmarineTransportation is unavailable")
                end
                remote:InvokeServer("GetAvailableLocations")
                if isCurrent() and self.RouteGeneration == routeGeneration then
                    remote:InvokeServer("InitiateTeleport", "Tiki Outpost")
                end
            end
        end)
        if not isCurrent() or self.RouteGeneration ~= routeGeneration then
            return
        end
        if ok then
            self.Report(route.Name .. " travel request submitted", "info")
        else
            self.Report("Travel request error: " .. tostring(err), "error")
        end
    end)
    return true
end

function MovementService:MoveTo(destination, options)
    options = options or {}
    if typeof(destination) ~= "CFrame" then
        return false, "Movement destination must be a CFrame"
    end

    local character, humanoid, root = self.Compatibility:GetCharacterParts()
    if not character or not humanoid or not root then
        return false, "Character is unavailable"
    end
    if self.LastStallAt and os.clock() - self.LastStallAt < 1 then
        return false, "Movement retry cooldown after a stall"
    end

    local route = self:_GetRoute(destination, root.Position)
    local goal = route and route.Stage or destination
    local threshold = route and 8 or (tonumber(options.Threshold) or 2.5)
    local isCurrent = options.IsCurrent or function()
        return true
    end

    local active = self.Active
    if active
        and active.Character == character
        and active.RouteName == (route and route.Name)
        and (active.Goal.Position - goal.Position).Magnitude <= 12
    then
        return true, "already moving"
    end

    if active
        and active.Character == character
        and active.KeepSession
        and options.KeepSession == true
        and not active.Route
        and not route
        and active.IsCurrent()
    then
        active.Goal = goal
        active.Threshold = threshold
        active.Speed = tonumber(options.Speed) or active.Speed
        active.IsCurrent = isCurrent
        active.Holding = false
        active.BestDistance = (goal.Position - root.Position).Magnitude
        active.LastProgressAt = os.clock()
        if active.BestDistance <= threshold then
            root.CFrame = destination
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            active.Holding = true
        end
        return true, active.Holding and "retargeted and holding" or "retargeted"
    end

    self:_StopMovement()
    if (goal.Position - root.Position).Magnitude <= threshold then
        if route then
            local requested, requestError = self:_RequestRoute(
                route,
                isCurrent,
                self.RouteGeneration
            )
            return requested, requestError or "at travel staging point"
        end
        root.CFrame = destination
        return true, "arrived"
    end

    self.Generation += 1
    self.TagGeneration += 1
    local generation = self.Generation
    local collisionOriginals = {}
    for _, descendant in ipairs(character:GetDescendants()) do
        if descendant:IsA("BasePart") then
            collisionOriginals[descendant] = descendant.CanCollide
            descendant.CanCollide = false
        end
    end

    local floatForce = root:FindFirstChild("FloatForce")
    local ownsFloatForce = false
    if not floatForce then
        floatForce = Instance.new("BodyVelocity")
        floatForce.Name = "FloatForce"
        floatForce.Velocity = Vector3.zero
        floatForce.MaxForce = Vector3.new(100000, 100000, 100000)
        floatForce.P = 10000
        floatForce.Parent = root
        ownsFloatForce = true
    end

    local hasTag = self.Compatibility.CollectionService:HasTag(
        self.Compatibility.Player,
        "Teleporting"
    )
    if not hasTag then
        self.Compatibility.CollectionService:AddTag(self.Compatibility.Player, "Teleporting")
        self.OwnsTeleportTag = true
    end

    active = {
        Character = character,
        Humanoid = humanoid,
        Root = root,
        Goal = goal,
        RouteName = route and route.Name,
        Route = route,
        Threshold = threshold,
        Speed = route and 190 or (tonumber(options.Speed) or 300),
        IsCurrent = isCurrent,
        Generation = generation,
        CollisionOriginals = collisionOriginals,
        FloatForce = ownsFloatForce and floatForce or nil,
        HasTeleportTag = self.OwnsTeleportTag,
        KeepSession = options.KeepSession == true and route == nil,
        Holding = false,
        BestDistance = (goal.Position - root.Position).Magnitude,
        LastProgressAt = os.clock(),
    }
    self.Active = active

    active.Connection = self.Compatibility.RunService.Heartbeat:Connect(function(deltaTime)
        if self.Active ~= active or self.Generation ~= generation or not active.IsCurrent() then
            self:_Finish(active, true)
            return
        end

        local currentCharacter, currentHumanoid, currentRoot = self.Compatibility:GetCharacterParts()
        if currentCharacter ~= character
            or currentHumanoid ~= humanoid
            or currentRoot ~= root
            or root.Anchored
        then
            self.LastStallAt = os.clock()
            self:_Finish(active, true)
            self.Report("Movement interrupted by character replacement or an anchored root", "warning")
            return
        end

        local goalNow = active.Goal
        local thresholdNow = active.Threshold
        local offset = goalNow.Position - root.Position
        local distance = offset.Magnitude
        if distance <= thresholdNow then
            root.CFrame = goalNow
            root.AssemblyLinearVelocity = Vector3.zero
            root.AssemblyAngularVelocity = Vector3.zero
            if active.KeepSession then
                active.Holding = true
                active.BestDistance = distance
                active.LastProgressAt = os.clock()
                return
            end
            self:_Finish(active, true)
            if active.Route then
                self:_RequestRoute(active.Route, active.IsCurrent, self.RouteGeneration)
            end
            return
        end
        active.Holding = false
        if distance < active.BestDistance - 1 then
            active.BestDistance = distance
            active.LastProgressAt = os.clock()
        elseif os.clock() - active.LastProgressAt > 2.5 then
            self.LastStallAt = os.clock()
            self:_Finish(active, true)
            self.Report("Movement stalled; cancelling this attempt before retry", "warning")
            return
        end

        local step = math.min(active.Speed * deltaTime, 18)
        if step <= 0 then
            return
        end
        local nextPosition = root.Position + offset.Unit * math.min(step, distance)
        root.CFrame = CFrame.new(nextPosition)
        root.AssemblyLinearVelocity = Vector3.zero
        root.AssemblyAngularVelocity = Vector3.zero
    end)

    return true, route and ("moving to " .. route.Name .. " staging") or "moving"
end

return MovementService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/MovementService.lua
end

__bundleFactories["CustomHub.Features.Farm.CombatService"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/CombatService.lua
local CombatService = {}
CombatService.__index = CombatService

local validHitPartNames = {
    RightUpperArm = true,
    RightLowerArm = true,
    RightHand = true,
    RightUpperLeg = true,
    RightLowerLeg = true,
    RightFoot = true,
    LeftUpperArm = true,
    LeftLowerArm = true,
    LeftHand = true,
    LeftUpperLeg = true,
    LeftLowerLeg = true,
    LeftFoot = true,
    UpperTorso = true,
    LowerTorso = true,
    Head = true,
}

function CombatService.new(compatibility, enemyService)
    local dependencies, dependencyError = compatibility:GetCombatDependencies()
    if not dependencies then
        return nil, dependencyError
    end
    return setmetatable({
        Compatibility = compatibility,
        EnemyService = enemyService,
        Dependencies = dependencies,
        AttackIndex = 0,
        FruitAttackIndex = 1,
    }, CombatService)
end

function CombatService:FindWeapon(category)
    local player = self.Compatibility.Player
    local backpack = player and player:FindFirstChild("Backpack")
    local character = player and player.Character
    if backpack then
        for _, item in ipairs(backpack:GetChildren()) do
            if item:IsA("Tool") and item.ToolTip == category then
                return item
            end
        end
    end
    if character then
        for _, item in ipairs(character:GetChildren()) do
            if item:IsA("Tool") and item.ToolTip == category then
                return item
            end
        end
    end
    return nil
end

function CombatService:EquipWeapon(category)
    local tool = self:FindWeapon(category)
    if not tool then
        return false, "No owned " .. tostring(category) .. " tool was found"
    end

    local character, humanoid = self.Compatibility:GetCharacterParts()
    if not character or not humanoid or humanoid.Sit then
        return false, "Character cannot equip a tool"
    end
    if tool.Parent ~= character then
        humanoid:EquipTool(tool)
    end
    if tool.Parent ~= character then
        return false, "Selected tool did not equip"
    end
    return true, tool
end

function CombatService:_FindBladeHitParts(character, root, range)
    local enemies = self.Compatibility.Workspace:FindFirstChild("Enemies")
    if not enemies then
        return {}
    end

    local parts = {}
    for _, model in ipairs(enemies:GetChildren()) do
        if model ~= character and model:IsDescendantOf(self.Compatibility.Workspace) then
            local targetRoot = model:FindFirstChild("HumanoidRootPart")
            if targetRoot then
                local effectiveRange = range
                local points = { targetRoot.Position }
                if targetRoot.Size.Y > 5 then
                    table.insert(
                        points,
                        (targetRoot.CFrame * CFrame.new(0, -targetRoot.Size.Y * 1.5 + 3, 0)).Position
                    )
                end

                for _, point in ipairs(points) do
                    if (point - root.Position).Magnitude < 10 + effectiveRange + targetRoot.Size.X / 2 then
                        for _, part in ipairs(model:GetChildren()) do
                            if part:IsA("BasePart")
                                and (part.Position - root.Position).Magnitude
                                    <= effectiveRange + targetRoot.Size.X / 2
                            then
                                table.insert(parts, part)
                            end
                        end
                        break
                    end
                end
            end
        end
    end
    return parts
end

function CombatService:_GetAttackCandidates(character, root, range)
    local combatUtil = self.Dependencies.CombatUtil
    local candidates, seenRigs = {}, {}
    for _, hitPart in ipairs(self:_FindBladeHitParts(character, root, range)) do
        local rig = combatUtil:GetRigOfHitPart(hitPart)
        if rig and not seenRigs[rig] and validHitPartNames[hitPart.Name] and combatUtil:IsVulnerable(rig) then
            local summoner = rig:FindFirstChild("Summoner")
            local ownSummoner = character:FindFirstChild("Summoner")
            local ownSummonerCharacter = ownSummoner and ownSummoner.Value
            local allowed = rig ~= character
                and (not ownSummonerCharacter or rig ~= ownSummonerCharacter.Character)
                and (not summoner
                    or summoner.Value ~= game:GetService("Players"):GetPlayerFromCharacter(character))
            if allowed then
                table.insert(candidates, { rig, hitPart })
                seenRigs[rig] = true
            end
        end
    end
    return candidates
end

function CombatService:_AttackFruitM1(target, character, root)
    local targetPart = target and (target.PrimaryPart or target:FindFirstChild("HumanoidRootPart"))
    if not targetPart then
        return false, "Fruit M1 target is unavailable"
    end

    local aimPosition = targetPart.Position
    local direction = aimPosition - root.Position
    if direction.Magnitude <= 0 then
        return false, "Fruit M1 target direction is unavailable"
    end
    direction = direction.Unit

    local tool = character:FindFirstChildOfClass("Tool")
    if not tool or tool.ToolTip ~= "Blox Fruit" then
        return false, "Selected fruit tool is not equipped"
    end

    local leftClickRemote = tool:FindFirstChild("LeftClickRemote")
    local remoteFunction = tool:FindFirstChild("RemoteFunction")
    local remoteEvent = tool:FindFirstChild("RemoteEvent")
    if not leftClickRemote and remoteFunction then
        if remoteEvent then
            remoteEvent:FireServer(aimPosition)
        end
        remoteFunction:InvokeServer("TAP")
        return true, "Fruit M1 request issued"
    end

    if leftClickRemote and tool.Name == "Mammoth-Mammoth" then
        leftClickRemote:FireServer(direction)
        return true, "Fruit M1 request issued"
    end
    if leftClickRemote then
        self.FruitAttackIndex += 1
        if self.FruitAttackIndex > 5 then
            self.FruitAttackIndex = 1
        end
        leftClickRemote:FireServer(direction, self.FruitAttackIndex)
        return true, "Fruit M1 request issued"
    end
    return false, "Selected fruit tool has no supported M1 remote"
end

function CombatService:AttackM1(target, range, weaponCategory, attackNoAnimation)
    local character, humanoid, root = self.Compatibility:GetCharacterParts()
    if not character or not humanoid or not root or not self.EnemyService:IsAlive(target) then
        return false, "Target or character is invalid"
    end

    local targetRoot = target:FindFirstChild("HumanoidRootPart")
    if not targetRoot or (root.Position - targetRoot.Position).Magnitude >= 70 then
        return false, "Target is outside ClickM1 range"
    end

    weaponCategory = weaponCategory or "Melee"
    local tool = character:FindFirstChildOfClass("Tool")
    if not tool or tool.ToolTip ~= weaponCategory then
        return false, "Selected weapon category is not equipped"
    end

    if weaponCategory == "Blox Fruit" then
        local fruitIssued, fruitResult = self:_AttackFruitM1(target, character, root)
        if fruitIssued then
            return true, fruitResult
        end
    end

    local stun = character:FindFirstChild("Stun")
    if not stun or stun.Value ~= 0 then
        return false, "Character is stunned or has no Stun state"
    end

    local candidates = self:_GetAttackCandidates(character, root, tonumber(range) or 30)
    if #candidates == 0 then
        return false, "No valid hit parts in BNN attack range"
    end

    local combatUtil = self.Dependencies.CombatUtil
    local weaponName = combatUtil:GetWeaponName(tool)
    local weaponData = combatUtil:GetWeaponData(weaponName)
    if not weaponData then
        return false, "CombatUtil weapon data is unavailable"
    end

    local weaponType = weaponData.WeaponType
    if not combatUtil:CanAttack(character, weaponType) then
        return false, "CombatUtil rejected attack timing"
    end

    local hitPart = table.remove(candidates, 1)[2]
    if attackNoAnimation == true then
        self.Dependencies.RegisterAttack:FireServer(0)
        self.Dependencies.RegisterHit:FireServer(hitPart, candidates)
        return true, "M1 request issued without animation"
    end

    local animationCache = combatUtil:GetMovesetAnimCache(humanoid)
    if not animationCache or not weaponData.Moveset or not weaponData.Moveset.Basic then
        return false, "CombatUtil moveset data is unavailable"
    end
    local basics = weaponData.Moveset.Basic
    if #basics == 0 then
        return false, "Weapon has no basic attack animations"
    end
    self.AttackIndex = self.AttackIndex % #basics + 1

    local pureWeaponName = combatUtil:GetPureWeaponName(weaponName)
    local animation = animationCache[pureWeaponName .. "-basic" .. self.AttackIndex]
    if not animation then
        return false, "Basic attack animation is not cached"
    end

    local speedMultiplier = animation:GetAttribute("SpeedMult") or 1
    if speedMultiplier <= 0 then
        speedMultiplier = 1
    end
    local duration = animation.Length / speedMultiplier

    self.Dependencies.RegisterAttack:FireServer(duration)
    self.Dependencies.RegisterHit:FireServer(hitPart, candidates)
    animation:Play(0.1, 1, speedMultiplier)

    return true, "M1 request issued"
end

function CombatService:Cancel()
    return true
end

return CombatService
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/Farm/CombatService.lua
end

__bundleFactories["CustomHub.Features.MainFarm"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/Features/MainFarm.lua
local QuestService = __bundleLoad("CustomHub.Features.Farm.QuestService")
local EnemyService = __bundleLoad("CustomHub.Features.Farm.EnemyService")
local MovementService = __bundleLoad("CustomHub.Features.Farm.MovementService")
local CombatService = __bundleLoad("CustomHub.Features.Farm.CombatService")

local QUEST_DIAGNOSTIC_INTERVAL = 1
local MAX_QUEST_DIAGNOSTIC_REPORT_LENGTH = 1400
local MAX_SPAWN_DIAGNOSTIC_REPORT_LENGTH = 1400
local QUEST_CONFIRMATION_TIMEOUT = 8
local QUEST_START_RETRY_INTERVAL = 2
local MAX_QUEST_START_ATTEMPTS = 3
local QUEST_DIALOGUE_RETREAT_DISTANCE = 32
local QUEST_DIALOGUE_RETREAT_INCREMENT = 24
local QUEST_DIALOGUE_MAX_RETREAT_DISTANCE = 80
local QUEST_DIALOGUE_MOVE_RETRY_INTERVAL = 0.5
local MAX_QUEST_DIALOGUE_MOVE_FAILURES = 3
local NPC_SCAN_INTERVAL = 0.35
local SPAWN_SCAN_INTERVAL = 0.5
local SPAWN_LOAD_GRACE = 1
local SPAWN_CYCLE_RETRY_INTERVAL = 2
local MAX_EMPTY_SPAWN_CYCLES = 2

local MainFarm = {
    Running = false,
    Session = 0,
    Context = nil,
}

local function diagnosticScalar(value)
    local valueType = typeof(value)
    if type(value) == "string" then
        local text = value:gsub("[%c]", " ")
        if #text > 80 then
            text = text:sub(1, 77) .. "..."
        end
        return string.format("%q", text)
    end
    if type(value) == "number" or type(value) == "boolean" then
        return tostring(value)
    end
    return "<" .. tostring(valueType) .. ">"
end

local function questKey(candidate)
    return tostring(candidate.QuestName) .. ":" .. tostring(candidate.Id)
end

local function horizontalUnitVector(vector)
    local horizontal = Vector3.new(vector.X, 0, vector.Z)
    if horizontal.Magnitude <= 0.01 then
        return nil
    end
    return horizontal.Unit
end

local function boundedReason(value)
    local text = tostring(value or "no validated active-quest signal observed")
        :gsub("[%c]", " ")
    if #text > 120 then
        text = text:sub(1, 117) .. "..."
    end
    return text
end

local function questDataSummary(label, snapshot)
    if type(snapshot) ~= "table" then
        return label .. ": unavailable"
    end
    return string.format(
        "%s: reader=%s Guide.Data=%s QuestData.present=%s type=%s Task.type=%s evidence=%s",
        label,
        tostring(snapshot.ReaderState),
        tostring(snapshot.GuideDataType),
        tostring(snapshot.QuestDataPresent),
        tostring(snapshot.QuestDataType),
        tostring(snapshot.TaskType),
        boundedReason(snapshot.ReaderEvidence)
    )
end

local function diagnosticSeaName(compatibility)
    local workspace = compatibility and compatibility.Workspace
    local mapReadOk, mapName = pcall(function()
        return workspace and workspace:GetAttribute("MAP")
    end)
    if mapReadOk then
        if mapName == "Sea1" then
            return "First Sea"
        elseif mapName == "Sea2" then
            return "Second Sea"
        elseif mapName == "Sea3" then
            return "Third Sea"
        end
    end
    if not compatibility then
        return "Unknown"
    end
    if type(compatibility.IsFirstSea) == "function" then
        local ok, isFirstSea = pcall(compatibility.IsFirstSea, compatibility)
        if ok and isFirstSea then
            return "First Sea"
        end
    end
    if type(compatibility.IsThirdSea) == "function" then
        local ok, isThirdSea = pcall(compatibility.IsThirdSea, compatibility)
        if ok and isThirdSea then
            return "Third Sea"
        end
    end
    return "Unknown"
end

function MainFarm:_SetStatus(message, kind)
    local now = os.clock()
    if self.LastStatus == message and now - (self.LastStatusAt or 0) < 1.5 then
        return
    end
    self.LastStatus = message
    self.LastStatusAt = now
    if self.Context and self.Context.State then
        self.Context.State:SetStatus(message, kind)
    end
end

function MainFarm:_EnsureBaseServices()
    if self.QuestService and self.EnemyService and self.MovementService then
        return true
    end

    local context = self.Context
    if not context or not context.Compatibility then
        return false, "Hub compatibility adapter is unavailable"
    end

    local questService, questError = QuestService.new(context.Compatibility)
    if not questService then
        return false, questError
    end
    self.QuestService = questService
    self.EnemyService = EnemyService.new(context.Compatibility)
    self.MovementService = MovementService.new(context.Compatibility, function(message, kind)
        self:_SetStatus(message, kind)
    end)
    return true
end

function MainFarm:_EnsureCombatService()
    if self.CombatService then
        return true
    end
    if self.CombatDependencyAttempted then
        if os.clock() - (self.LastCombatDependencyAttemptAt or 0) < 5 then
            return false, self.CombatDependencyError
        end
    end
    self.CombatDependencyAttempted = true
    self.LastCombatDependencyAttemptAt = os.clock()
    local combatService, combatError = CombatService.new(
        self.Context.Compatibility,
        self.EnemyService
    )
    if not combatService then
        self.CombatDependencyError = combatError
        return false, combatError
    end
    self.CombatService = combatService
    return true
end

function MainFarm:_IsCurrent(session)
    return self.Running and self.Session == session
end

function MainFarm:_LogQuestDataSnapshot(phase, questState, force, readerEvidence)
    pcall(function()
        local report = self.QuestDiagnosticReport
        if type(report) ~= "table" then
            return
        end

        local guide = self.QuestService and self.QuestService.Guide
        local guideData = type(guide) == "table" and guide.Data or nil
        local guideDataType = type(guideData)
        local questData = guideDataType == "table" and guideData.QuestData or nil
        local questDataType = type(questData)
        local taskType = questDataType == "table" and type(questData.Task) or "n/a"
        local questDataPresent = questData ~= nil
        local signature = table.concat({
            tostring(phase),
            tostring(guideDataType),
            questDataPresent and "present" or "nil",
            tostring(questDataType),
            tostring(taskType),
            tostring(questState),
            boundedReason(readerEvidence),
        }, "|")
        local now = os.clock()
        if not force
            and signature == self.LastQuestDiagnosticSignature
            and now - (self.LastQuestDiagnosticAt or 0) < QUEST_DIAGNOSTIC_INTERVAL
        then
            return
        end

        self.LastQuestDiagnosticSignature = signature
        self.LastQuestDiagnosticAt = now
        local snapshot = {
            ReaderState = tostring(questState),
            GuideDataType = tostring(guideDataType),
            QuestDataPresent = tostring(questDataPresent),
            QuestDataType = tostring(questDataType),
            TaskType = tostring(taskType),
            ReaderEvidence = boundedReason(readerEvidence),
        }
        report.LatestQuestData = snapshot
        if phase == "post_request" then
            report.PostRequestQuestData = snapshot
        end
    end)
end

function MainFarm:_PrintQuestDiagnosticReport(report, reason, elapsed)
    pcall(function()
        local pcallOutcome
        if type(report.PcallSucceeded) == "boolean" then
            pcallOutcome = tostring(report.PcallSucceeded)
                .. (report.PcallSucceeded and " (returned; acceptance not inferred)"
                    or " (call raised inside pcall)")
        else
            pcallOutcome = "not reached (stage=" .. tostring(report.RequestStage) .. ")"
        end

        local lines = {
            "===== [QuestDiagnostic] REPORT BEGIN =====",
            "Sea: " .. diagnosticSeaName(self.Context and self.Context.Compatibility),
            "Dialogue deferred: " .. tostring(report.DialogueDeferred == true),
            "Candidate: quest=" .. tostring(report.CandidateQuestName)
                .. " id=" .. tostring(report.CandidateQuestId),
            "StartQuest: pcall_succeeded=" .. pcallOutcome
                .. " attempts=" .. tostring(report.AttemptCount or 0),
            "Result: type=" .. tostring(report.ResultType)
                .. " summary=" .. tostring(report.ResultSummary),
            questDataSummary("QuestData after request", report.PostRequestQuestData),
            questDataSummary("QuestData at end", report.LatestQuestData),
            string.format(
                "Confirmation: %s; elapsed_seconds=%.2f",
                tostring(reason),
                math.max(0, elapsed)
            ),
            "===== [QuestDiagnostic] REPORT END =====",
        }
        local text = table.concat(lines, "\n")
        if #text > MAX_QUEST_DIAGNOSTIC_REPORT_LENGTH then
            local endMarker = "\n===== [QuestDiagnostic] REPORT END ====="
            text = text:sub(1, MAX_QUEST_DIAGNOSTIC_REPORT_LENGTH - #endMarker - 18)
                .. "\n...[truncated]" .. endMarker
        end

        self.LastQuestDiagnosticReportText = text
        local copied = false
        local clipboardCallOk = pcall(function()
            if type(setclipboard) == "function" then
                setclipboard(text)
                copied = true
            end
        end)
        if clipboardCallOk and copied then
            print("[QuestDiagnostic] Clipboard copy succeeded.")
        else
            print(text)
        end
    end)
end

function MainFarm:CopyStatusReport()
    local text = self.LastQuestDiagnosticReportText
    if type(text) ~= "string" or text == "" then
        self:_SetStatus("No completed quest status report is available yet.", "warning")
        return true
    end

    local copied = false
    local clipboardCallOk = pcall(function()
        if type(setclipboard) == "function" then
            setclipboard(text)
            copied = true
        end
    end)
    if clipboardCallOk and copied then
        self:_SetStatus("Complete quest status report copied to clipboard.", "success")
    else
        print(text)
        self:_SetStatus("Clipboard unavailable; complete report printed to output.", "warning")
    end
    return true
end

function MainFarm:_PrintSpawnDiagnosticReport(report)
    pcall(function()
        local selected
        if report.SelectedName then
            local distance = type(report.SelectedDistance) == "number"
                and report.SelectedDistance == report.SelectedDistance
                and report.SelectedDistance < math.huge
                and string.format("%.1f", report.SelectedDistance)
                or "n/a"
            selected = "source=" .. tostring(report.SelectedSource)
                .. " name=" .. diagnosticScalar(report.SelectedName)
                .. " distance=" .. distance
        else
            selected = "none"
        end

        local moveAccepted = report.MovementAccepted == nil
            and "not_called"
            or tostring(report.MovementAccepted == true)
        local availability = report.IsSpawnAvailable == nil
            and "not_called_no_candidate"
            or tostring(report.IsSpawnAvailable == true)
        local lines = {
            "===== [SpawnDiagnostic] REPORT BEGIN =====",
            "Target NPC: " .. diagnosticScalar(report.TargetName),
            "EnemySpawns container found: "
                .. tostring(report.EnemySpawnsContainerFound == true),
            "Normal EnemySpawns marker: " .. tostring(report.NormalMarkerFound == true),
            "Hidden unparented marker: " .. tostring(report.HiddenMarkerFound == true)
                .. " (discovery_available="
                .. tostring(report.HiddenDiscoveryAvailable == true) .. ")",
            "Selected candidate: " .. selected,
            "IsSpawnAvailable: " .. availability,
            "MovementService:MoveTo accepted=" .. moveAccepted
                .. " started_this_call=" .. tostring(report.MovementStarted == true)
                .. " result=" .. diagnosticScalar(report.MovementResult or "not_called"),
            "===== [SpawnDiagnostic] REPORT END =====",
        }
        local text = table.concat(lines, "\n")
        if #text > MAX_SPAWN_DIAGNOSTIC_REPORT_LENGTH then
            local endMarker = "\n===== [SpawnDiagnostic] REPORT END ====="
            text = text:sub(1, MAX_SPAWN_DIAGNOSTIC_REPORT_LENGTH - #endMarker - 18)
                .. "\n...[truncated]" .. endMarker
        end

        local copied = false
        local clipboardCallOk = pcall(function()
            if type(setclipboard) == "function" then
                setclipboard(text)
                copied = true
            end
        end)
        if clipboardCallOk and copied then
            print("[SpawnDiagnostic] Clipboard copy succeeded.")
        else
            print(text)
        end
    end)
end

function MainFarm:_RecordSpawnDiagnostic(
    targetName,
    discovery,
    candidate,
    isAvailable,
    movementAccepted,
    movementResult
)
    local report = type(discovery) == "table" and discovery or {}
    report.TargetName = targetName
    report.IsSpawnAvailable = isAvailable
    report.MovementAccepted = movementAccepted
    report.MovementResult = movementResult
    report.MovementStarted = movementAccepted == true
        and (
            movementResult == "moving"
            or movementResult == "retargeted"
            or (
                type(movementResult) == "string"
                and movementResult:sub(1, 10) == "moving to "
            )
        )
    if candidate and not report.SelectedName then
        local candidateNameOk, candidateName = pcall(function()
            return candidate.Name
        end)
        if candidateNameOk then
            report.SelectedName = candidateName
        end
    end

    local signature = table.concat({
        tostring(report.TargetName),
        tostring(report.NormalMarkerFound == true),
        tostring(report.HiddenMarkerFound == true),
        tostring(report.HiddenDiscoveryAvailable == true),
        tostring(report.SelectedSource),
        tostring(report.SelectedName),
        tostring(report.IsSpawnAvailable),
        tostring(report.MovementAccepted),
        tostring(report.MovementStarted),
        tostring(report.MovementResult),
    }, "|")
    if signature == self.LastSpawnDiagnosticSignature then
        return
    end
    self.LastSpawnDiagnosticSignature = signature
    self:_PrintSpawnDiagnosticReport(report)
end

function MainFarm:_EndQuestDiagnosticWait(reason, now)
    local key = self.QuestDiagnosticWaitKey
    if not key then
        return
    end

    pcall(function()
        local startedAt = self.QuestDiagnosticWaitStartedAt or now
        self:_PrintQuestDiagnosticReport(
            self.QuestDiagnosticReport or {},
            reason,
            math.max(0, now - startedAt)
        )
    end)
    self.QuestDiagnosticWaitKey = nil
    self.QuestDiagnosticWaitStartedAt = nil
    self.QuestDiagnosticReport = nil
end

function MainFarm:_MoveTo(destination, session, threshold, keepSession)
    if not self.MovementService then
        return false
    end
    return self.MovementService:MoveTo(destination, {
        Speed = 190,
        Threshold = threshold,
        KeepSession = keepSession == true,
        IsCurrent = function()
            return self:_IsCurrent(session)
        end,
    })
end

function MainFarm:_HandleQuestDialogueRecovery(candidate, giverCFrame, root, session)
    local key = questKey(candidate)
    local recovery = self.QuestDialogueRecovery
    if recovery and recovery.CandidateKey ~= key then
        self.QuestDialogueRecovery = nil
        self.MovementService:Cancel()
        recovery = nil
    end

    local dialogueOpen = self.QuestService:IsQuestGiverDialogueOpen()
    if not dialogueOpen then
        if recovery then
            self.QuestDialogueRecovery = nil
            self.QuestDeferredForDialogue = true
            self.PendingQuestReachedAt = os.clock() - 2
        end
        return false
    end

    if not recovery then
        local direction = horizontalUnitVector(root.Position - giverCFrame.Position)
        if not direction then
            direction = horizontalUnitVector(-root.CFrame.LookVector)
                or Vector3.new(1, 0, 0)
        end
        recovery = {
            CandidateKey = key,
            Direction = direction,
            RetreatDistance = QUEST_DIALOGUE_RETREAT_DISTANCE,
            NextMoveAt = 0,
            MoveFailures = 0,
        }
        self.QuestDialogueRecovery = recovery
    end

    self.QuestDeferredForDialogue = true
    self.PendingQuestReachedAt = nil
    if self.TimedOutQuestKey == key then
        self.TimedOutQuestKey = nil
        self.QuestTimeoutReason = nil
        self.LastQuestAttemptKey = nil
        self.LastQuestAttemptAt = 0
        self.QuestStartAttemptCount = 0
    end

    if recovery.MoveFailures >= MAX_QUEST_DIALOGUE_MOVE_FAILURES then
        self:_SetStatus(
            "Could not move away from quest dialogue; move away manually to retry",
            "warning"
        )
        return true
    end

    local offset = root.Position - giverCFrame.Position
    local currentDistance = Vector3.new(offset.X, 0, offset.Z).Magnitude
    if currentDistance >= recovery.RetreatDistance - 3 then
        if recovery.RetreatDistance >= QUEST_DIALOGUE_MAX_RETREAT_DISTANCE then
            self:_SetStatus(
                "Quest dialogue is still open; move farther from the giver to retry",
                "warning"
            )
            return true
        end
        recovery.RetreatDistance = math.min(
            QUEST_DIALOGUE_MAX_RETREAT_DISTANCE,
            recovery.RetreatDistance + QUEST_DIALOGUE_RETREAT_INCREMENT
        )
    end

    local now = os.clock()
    if now >= (recovery.NextMoveAt or 0) then
        local giverPosition = giverCFrame.Position
        local retreatPosition = Vector3.new(
            giverPosition.X + recovery.Direction.X * recovery.RetreatDistance,
            root.Position.Y,
            giverPosition.Z + recovery.Direction.Z * recovery.RetreatDistance
        )
        local moveAccepted, moveResult = self:_MoveTo(
            CFrame.new(retreatPosition),
            session,
            4,
            true
        )
        recovery.NextMoveAt = now + QUEST_DIALOGUE_MOVE_RETRY_INTERVAL
        if moveAccepted then
            recovery.MoveFailures = 0
        else
            recovery.MoveFailures = recovery.MoveFailures + 1
        end
    end

    if recovery.MoveFailures >= MAX_QUEST_DIALOGUE_MOVE_FAILURES then
        self:_SetStatus(
            "Could not move away from quest dialogue; move away manually to retry",
            "warning"
        )
    else
        self:_SetStatus("Quest dialogue open; moving away to dismiss it", "info")
    end
    return true
end

function MainFarm:_ClearTarget(preserveMovement)
    local hadTarget = self.Target ~= nil or self.TargetName ~= nil
    if hadTarget then
        if self.EnemyService then
            self.EnemyService:RestoreTargetCollision()
        end
        if self.MovementService and not preserveMovement then
            self.MovementService:Cancel()
        end
    end
    self.Target = nil
    self.TargetName = nil
end

function MainFarm:_ResetSpawnSearch(targetName)
    if self.SpawnSearchTarget ~= targetName then
        self.LastSpawnDiagnosticSignature = nil
    end
    if self.EnemyService then
        self.EnemyService:ClearIgnoredSpawns()
    end
    self.SpawnSearchTarget = targetName
    self.SpawnCandidate = nil
    self.SpawnCandidateDiagnostic = nil
    self.SpawnLoading = nil
    self.SpawnRetryAt = nil
    self.SpawnEmptyCycles = 0
    self.SpawnSearchExhausted = false
    self.NextSpawnSearchAt = 0
    self.NextEnemySearchAt = 0
end

function MainFarm:_TimeoutQuestConfirmation(key, now)
    if key ~= self.QuestDiagnosticWaitKey and key ~= self.LastQuestAttemptKey then
        return
    end
    local reason = boundedReason(self.LastQuestStateReason)
    self.TimedOutQuestKey = key
    self.QuestTimeoutReason = reason
    self:_EndQuestDiagnosticWait("cooldown_elapsed_without_active_state", now)
    self:_SetStatus(
        "Quest confirmation timed out after 8 seconds: " .. reason,
        "error"
    )
end

function MainFarm:_RequestQuest(candidate, session)
    local key = questKey(candidate)
    local now = os.clock()
    if self.QuestDiagnosticWaitKey and self.QuestDiagnosticWaitKey ~= key then
        self:_EndQuestDiagnosticWait("candidate_changed_before_confirmation", now)
    end
    if self.TimedOutQuestKey == key then
        self:_SetStatus(
            "Quest confirmation timed out: " .. boundedReason(self.QuestTimeoutReason)
                .. "; toggle Main Farm to retry",
            "error"
        )
        return
    end
    local isNewCandidate = self.LastQuestAttemptKey ~= key
    if isNewCandidate then
        self.LastQuestAttemptKey = key
        self.LastQuestAttemptAt = 0
        self.QuestStartAttemptCount = 0
        self.QuestDiagnosticWaitKey = key
        self.QuestDiagnosticWaitStartedAt = now
        self.LastQuestDiagnosticReportText = nil
        self.QuestDiagnosticReport = {
            CandidateQuestName = diagnosticScalar(candidate.QuestName),
            CandidateQuestId = diagnosticScalar(candidate.Id),
            DialogueDeferred = self.QuestDeferredForDialogue == true,
            RequestStage = "pcall_not_reached",
            PcallSucceeded = nil,
            ResultType = "n/a",
            ResultSummary = "not returned",
            AttemptCount = 0,
        }
        self.QuestDeferredForDialogue = false
        self.PendingQuestTargetName = candidate.Mob
    end

    local confirmationStartedAt = self.QuestDiagnosticWaitStartedAt or now
    if now - confirmationStartedAt >= QUEST_CONFIRMATION_TIMEOUT then
        self:_TimeoutQuestConfirmation(key, now)
        return
    end

    local attempts = self.QuestStartAttemptCount or 0
    if attempts >= MAX_QUEST_START_ATTEMPTS then
        self:_SetStatus(
            "Waiting for active quest confirmation; "
                .. boundedReason(self.LastQuestStateReason),
            "warning"
        )
        return
    end
    if attempts > 0 and now - (self.LastQuestAttemptAt or 0) < QUEST_START_RETRY_INTERVAL then
        self:_SetStatus(
            "Waiting for active quest confirmation; "
                .. boundedReason(self.LastQuestStateReason),
            "warning"
        )
        return
    end

    self.LastQuestAttemptAt = now
    self.QuestStartAttemptCount = attempts + 1
    self.QuestDiagnosticReport.AttemptCount = self.QuestStartAttemptCount
    self.PendingQuestTargetName = candidate.Mob
    self:_SetStatus(
        "Requesting quest: " .. tostring(candidate.QuestName) .. " (ID "
            .. tostring(candidate.Id) .. ", attempt "
            .. tostring(self.QuestStartAttemptCount) .. "/" .. tostring(MAX_QUEST_START_ATTEMPTS)
            .. ")",
        "info"
    )
    local requested = self.QuestService:RequestStart(candidate)
    local requestDiagnostic = self.QuestService.LastStartDiagnostic
    if type(requestDiagnostic) == "table" then
        self.QuestDiagnosticReport.RequestStage = tostring(requestDiagnostic.Stage)
        self.QuestDiagnosticReport.PcallSucceeded = requestDiagnostic.PcallSucceeded
        self.QuestDiagnosticReport.ResultType = tostring(requestDiagnostic.ResultType)
        self.QuestDiagnosticReport.ResultSummary = tostring(requestDiagnostic.ResultSummary)
    end
    local stateReadOk, stateAfterRequest, activeTargetAfterRequest, readerEvidence = pcall(function()
        return self.QuestService:GetActiveQuestState()
    end)
    if not stateReadOk then
        stateAfterRequest = "diagnostic_read_error"
        activeTargetAfterRequest = nil
        readerEvidence = "active quest state reader raised an error"
    end
    self.LastQuestStateReason = readerEvidence
    self:_LogQuestDataSnapshot("post_request", stateAfterRequest, true, readerEvidence)
    if stateAfterRequest == "active" then
        if activeTargetAfterRequest == candidate.Mob then
            self:_EndQuestDiagnosticWait("active_state_observed", os.clock())
            self.TimedOutQuestKey = nil
            self.LastQuestAttemptKey = nil
            self.LastQuestAttemptAt = 0
            self.QuestStartAttemptCount = 0
            self.PendingQuestTargetName = nil
            self.PendingQuestKey = nil
            self.PendingQuestReachedAt = nil
            self:_SetStatus(
                "Quest confirmed by " .. boundedReason(readerEvidence),
                "success"
            )
        else
            self:_EndQuestDiagnosticWait("active_state_target_mismatch", os.clock())
            self.LastQuestAttemptKey = nil
            self.LastQuestAttemptAt = 0
            self.QuestStartAttemptCount = 0
            self.PendingQuestTargetName = nil
            self.PendingQuestKey = nil
            self.PendingQuestReachedAt = nil
            self:_SetStatus(
                "A different active quest target was observed; following its validated target",
                "warning"
            )
        end
    end
    if not self:_IsCurrent(session) then
        return
    end
    if stateAfterRequest ~= "active" then
        local message = requested
            and "StartQuest call returned; waiting for state evidence (response is not acceptance)"
            or "StartQuest call raised; quest acceptance remains unconfirmed"
        self:_SetStatus(message, "warning")
    elseif activeTargetAfterRequest ~= candidate.Mob then
        self:_SetStatus(
            "A different active quest target was observed; following its validated target",
            "warning"
        )
    end
end

function MainFarm:_Step(session)
    if not self:_IsCurrent(session) then
        return
    end

    local compatibility = self.Context.Compatibility
    local character, humanoid, root = compatibility:GetCharacterParts()
    if not character or not humanoid or not root then
        if self.MovementService then
            self.MovementService:Cancel()
        end
        self:_ClearTarget()
        self:_SetStatus("Waiting for a living character and HumanoidRootPart", "warning")
        return
    end

    if self.Character ~= character then
        if self.MovementService then
            self.MovementService:Cancel()
        end
        if self.EnemyService then
            self.EnemyService:RestoreTargetCollision()
        end
        self.Character = character
        self.Target = nil
        self.TargetName = nil
        self:_ResetSpawnSearch(nil)
        self:_SetStatus("Character ready; reacquiring farm state", "info")
    end

    local questState, activeTarget, readerEvidence = self.QuestService:GetActiveQuestState()
    self.LastQuestStateReason = readerEvidence
    if questState == "active" then
        self.QuestDeferredForDialogue = false
        if self.QuestDialogueRecovery then
            self.MovementService:Cancel()
            self.QuestDialogueRecovery = nil
            self.PendingQuestReachedAt = nil
        end
    end
    if self.QuestDiagnosticWaitKey then
        self:_LogQuestDataSnapshot("confirmation_poll", questState, false, readerEvidence)
        local now = os.clock()
        if questState == "active" then
            self:_LogQuestDataSnapshot("confirmation_poll", questState, true, readerEvidence)
            if activeTarget == self.PendingQuestTargetName then
                self:_EndQuestDiagnosticWait("active_state_observed", now)
                self.TimedOutQuestKey = nil
                self.LastQuestAttemptKey = nil
                self.LastQuestAttemptAt = 0
                self.QuestStartAttemptCount = 0
                self.PendingQuestTargetName = nil
                self.PendingQuestKey = nil
                self.PendingQuestReachedAt = nil
                self:_SetStatus(
                    "Quest confirmed by " .. boundedReason(readerEvidence),
                    "success"
                )
            else
                self:_EndQuestDiagnosticWait("active_state_target_mismatch", now)
                self.LastQuestAttemptKey = nil
                self.LastQuestAttemptAt = 0
                self.QuestStartAttemptCount = 0
                self.PendingQuestTargetName = nil
                self.PendingQuestKey = nil
                self.PendingQuestReachedAt = nil
                self:_SetStatus(
                    "A different active quest target was observed; following its validated target",
                    "warning"
                )
            end
        elseif self.QuestService:IsQuestGiverDialogueOpen() then
            self.QuestDiagnosticWaitStartedAt = nil
            self.LastQuestAttemptKey = nil
            self.LastQuestAttemptAt = 0
            self.QuestStartAttemptCount = 0
            self.QuestDeferredForDialogue = true
            self:_SetStatus(
                "Quest dialogue open; preparing recovery before requesting",
                "info"
            )
        elseif not self.QuestDiagnosticWaitStartedAt then
            self.QuestDiagnosticWaitStartedAt = now
        elseif now - self.QuestDiagnosticWaitStartedAt >= QUEST_CONFIRMATION_TIMEOUT then
            self:_LogQuestDataSnapshot("confirmation_poll", questState, true, readerEvidence)
            self:_TimeoutQuestConfirmation(self.QuestDiagnosticWaitKey, now)
        end
    end
    if questState == "active"
        and self.PendingQuestTargetName
        and activeTarget == self.PendingQuestTargetName
    then
        self.TimedOutQuestKey = nil
        self.QuestTimeoutReason = nil
        self.LastQuestAttemptKey = nil
        self.LastQuestAttemptAt = 0
        self.QuestStartAttemptCount = 0
        self.PendingQuestTargetName = nil
        self.PendingQuestKey = nil
        self.PendingQuestReachedAt = nil
        self:_SetStatus(
            "Quest confirmed by " .. boundedReason(readerEvidence),
            "success"
        )
    end
    if questState == "unknown" then
        self:_ClearTarget(true)
        self:_SetStatus(
            "Quest reader: " .. boundedReason(readerEvidence),
            "warning"
        )
        return
    elseif questState == "active-unknown" then
        self:_ClearTarget(true)
        self:_SetStatus(
            "Waiting: quest UI is active but its catalog target is unresolved; "
                .. boundedReason(readerEvidence),
            "warning"
        )
        return
    elseif questState == "none" then
        self:_ClearTarget(true)
        local candidate, selectionError = self.QuestService:SelectLevelQuest()
        if not candidate then
            self.MovementService:Cancel()
            self:_SetStatus("Quest selection unavailable: " .. tostring(selectionError), "error")
            return
        end

        local giverPosition = candidate.Pos
        if typeof(giverPosition) ~= "Vector3" and typeof(giverPosition) ~= "CFrame" then
            self.MovementService:Cancel()
            self:_SetStatus("Selected quest giver has no usable position", "error")
            return
        end
        local candidateKey = questKey(candidate)
        if self.PendingQuestKey ~= candidateKey then
            self.PendingQuestKey = candidateKey
            self.PendingQuestReachedAt = nil
        end
        local giverCFrame = typeof(giverPosition) == "CFrame"
            and giverPosition
            or CFrame.new(giverPosition)
        if self.QuestDialogueRecovery
            and self:_HandleQuestDialogueRecovery(candidate, giverCFrame, root, session)
        then
            return
        end
        if (root.Position - giverCFrame.Position).Magnitude > 8 then
            if not self.QuestDeferredForDialogue then
                self.PendingQuestReachedAt = nil
            end
            self:_MoveTo(giverCFrame * CFrame.new(0, 4, 2), session, 8, true)
            self:_SetStatus("Approaching quest giver: " .. tostring(candidate.Name), "info")
            return
        end
        if not self.PendingQuestReachedAt then
            if self.QuestDeferredForDialogue then
                self.PendingQuestReachedAt = os.clock() - 2
            else
                self.PendingQuestReachedAt = os.clock()
                self:_SetStatus("At quest giver; waiting before quest request", "info")
                return
            end
        elseif os.clock() - self.PendingQuestReachedAt < 2 then
            return
        end
        if self:_HandleQuestDialogueRecovery(candidate, giverCFrame, root, session) then
            return
        end
        self:_RequestQuest(candidate, session)
        return
    end

    if self.TargetName ~= activeTarget then
        self:_ClearTarget(true)
        self:_ResetSpawnSearch(activeTarget)
        self.TargetName = activeTarget
    end

    local now = os.clock()
    local target
    if self.Target and self.TargetName == activeTarget and self.EnemyService:IsAlive(self.Target) then
        target = self.Target
    elseif now >= (self.NextEnemySearchAt or 0) then
        target = self.EnemyService:FindNearest(activeTarget, root.Position)
        self.NextEnemySearchAt = now + NPC_SCAN_INTERVAL
    end
    if not target then
        if self.Target then
            self:_ClearTarget(true)
            self.TargetName = activeTarget
        end
        if self.SpawnSearchExhausted then
            self:_SetStatus(
                "No living " .. activeTarget
                    .. " was found after two spawn cycles; continuing throttled scans of loaded NPCs",
                "warning"
            )
            return
        end
        if self.SpawnRetryAt and now < self.SpawnRetryAt then
            self:_SetStatus(
                "No living " .. activeTarget .. " after checking known spawns; retrying shortly",
                "warning"
            )
            return
        elseif self.SpawnRetryAt then
            self.SpawnRetryAt = nil
            self.NextSpawnSearchAt = 0
        end

        local spawnPart = self.SpawnCandidate
        local spawnDiagnostic = self.SpawnCandidateDiagnostic
        local allSpawnsVisited = false
        if now >= (self.NextSpawnSearchAt or 0) then
            spawnPart, allSpawnsVisited, spawnDiagnostic =
                self.EnemyService:FindSpawn(activeTarget, root.Position)
            self.SpawnCandidate = spawnPart
            self.SpawnCandidateDiagnostic = spawnDiagnostic
            self.NextSpawnSearchAt = now + SPAWN_SCAN_INTERVAL
        end
        if spawnPart then
            local spawnAvailable =
                self.EnemyService:IsSpawnAvailable(spawnPart, activeTarget)
            if not spawnAvailable then
                self:_RecordSpawnDiagnostic(
                    activeTarget,
                    spawnDiagnostic,
                    spawnPart,
                    false,
                    nil,
                    "not_called_unavailable"
                )
                self.SpawnCandidate = nil
                self.SpawnLoading = nil
                self.NextSpawnSearchAt = 0
                self:_SetStatus(
                    "A matching enemy spawn marker is stale or ignored; rescanning",
                    "warning"
                )
                return
            end
            local spawnDestination = spawnPart.CFrame * CFrame.new(0, 60, 0)
            local movementAccepted, movementResult =
                self:_MoveTo(spawnDestination, session, 100, true)
            self:_RecordSpawnDiagnostic(
                activeTarget,
                spawnDiagnostic,
                spawnPart,
                true,
                movementAccepted,
                movementResult
            )
            if (spawnPart.Position - root.Position).Magnitude <= 100 then
                if not self.SpawnLoading
                    or self.SpawnLoading.TargetName ~= activeTarget
                    or self.SpawnLoading.Part ~= spawnPart
                then
                    self.SpawnLoading = {
                        TargetName = activeTarget,
                        Part = spawnPart,
                        ArrivedAt = now,
                    }
                elseif now - self.SpawnLoading.ArrivedAt >= SPAWN_LOAD_GRACE then
                    self.EnemyService:MarkSpawnIgnored(spawnPart, activeTarget)
                    self.SpawnLoading = nil
                    self.SpawnCandidate = nil
                    self.NextSpawnSearchAt = 0
                    self.NextEnemySearchAt = 0
                    self:_SetStatus(
                        "No living " .. activeTarget .. " loaded at this spawn; checking the next location",
                        "warning"
                    )
                    return
                end
                local elapsed = self.SpawnLoading and now - self.SpawnLoading.ArrivedAt or 0
                self:_SetStatus(
                    "Waiting for " .. activeTarget .. " to load at spawn ("
                        .. tostring(math.max(0, math.ceil(SPAWN_LOAD_GRACE - elapsed)))
                        .. "s)",
                    "info"
                )
            else
                if self.SpawnLoading and self.SpawnLoading.Part ~= spawnPart then
                    self.SpawnLoading = nil
                end
                self:_SetStatus("Travelling to supported spawn for " .. activeTarget, "info")
            end
        else
            self:_RecordSpawnDiagnostic(
                activeTarget,
                spawnDiagnostic,
                nil,
                nil,
                nil,
                "not_called_no_candidate"
            )
            if allSpawnsVisited then
                self.EnemyService:ClearIgnoredSpawns()
                self.SpawnCandidate = nil
                self.SpawnLoading = nil
                self.SpawnEmptyCycles = (self.SpawnEmptyCycles or 0) + 1
                if self.SpawnEmptyCycles >= MAX_EMPTY_SPAWN_CYCLES then
                    self.SpawnSearchExhausted = true
                    self.SpawnRetryAt = nil
                    self.NextSpawnSearchAt = math.huge
                    self:_SetStatus(
                        "No living " .. activeTarget
                            .. " after two spawn cycles; continuing throttled scans of loaded NPCs",
                        "warning"
                    )
                else
                    self.SpawnRetryAt = now + SPAWN_CYCLE_RETRY_INTERVAL
                    self.NextSpawnSearchAt = self.SpawnRetryAt
                    self:_SetStatus(
                        "No living " .. activeTarget
                            .. " at known spawns; retrying once after a short pause",
                        "warning"
                    )
                end
            else
                self.SpawnCandidate = nil
                self.SpawnLoading = nil
                self:_SetStatus(
                    "No eligible " .. activeTarget
                        .. " is loaded and no matching Workspace._WorldOrigin.EnemySpawns marker is available",
                    "warning"
                )
            end
        end
        return
    end

    if self.SpawnSearchTarget ~= activeTarget or self.SpawnSearchExhausted then
        self:_ResetSpawnSearch(activeTarget)
    end
    self.SpawnEmptyCycles = 0
    self.SpawnSearchExhausted = false
    self.SpawnCandidate = nil
    self.SpawnLoading = nil
    self.SpawnRetryAt = nil
    self.NextSpawnSearchAt = 0
    if self.Target ~= target then
        self:_ClearTarget(true)
        self.Target = target
        self.TargetName = activeTarget
        self:_SetStatus("Target acquired: " .. activeTarget, "success")
    end
    if not self.EnemyService:IsAlive(target) then
        self:_ClearTarget(true)
        self:_SetStatus("Target died or became invalid; reacquiring", "info")
        return
    end

    self.EnemyService:PrepareTarget(target, root)
    local farmSettings = self.Context.Config and self.Context.Config.FarmSettings
    local weaponCategory = farmSettings and farmSettings.WeaponCategory or "Melee"
    local combatReady, combatError = self:_EnsureCombatService()
    if combatReady then
        local equipped, equipResult = self.CombatService:EquipWeapon(weaponCategory)
        if equipped then
            local attackIssued, attackResult = self.CombatService:AttackM1(
                target,
                30,
                weaponCategory,
                farmSettings and farmSettings.AttackNoAnimation == true
            )
            if attackIssued then
                self:_SetStatus("M1 request issued; server damage is not yet confirmed", "info")
            else
                self:_SetStatus("Combat waiting: " .. tostring(attackResult), "warning")
            end
        else
            self:_SetStatus("Combat waiting: " .. tostring(equipResult), "warning")
        end
    else
        self:_SetStatus("Combat dependencies unavailable: " .. tostring(combatError), "error")
    end

    if self.EnemyService:IsAlive(target) then
        local targetRoot = target:FindFirstChild("HumanoidRootPart")
        if targetRoot then
            local targetOffset = weaponCategory == "Blox Fruit"
                and CFrame.new(-7, 20, 0)
                or CFrame.new(7, 20, 0)
            self:_MoveTo(targetRoot.CFrame * targetOffset, session, 2.5, true)
            if (root.Position - targetRoot.Position).Magnitude >= 30 then
                self:_SetStatus("Approaching target: " .. activeTarget, "info")
            end
        end
    else
        self:_ClearTarget(true)
        self:_SetStatus("Target died or became invalid; reacquiring", "info")
    end
end

function MainFarm:_Run(session)
    while self:_IsCurrent(session) do
        local ok, err = pcall(self._Step, self, session)
        if not ok then
            if self.MovementService then
                self.MovementService:Cancel()
            end
            self.QuestDialogueRecovery = nil
            if self.EnemyService then
                self.EnemyService:RestoreTargetCollision()
            end
            self.Target = nil
            self.TargetName = nil
            self:_SetStatus("Main Farm step error: " .. tostring(err), "error")
        end
        task.wait()
    end
end

function MainFarm:Initialize(context)
    self.Context = context
    self.Running = false
    self.Session += 1
    self.Character = nil
    self.Target = nil
    self.TargetName = nil
    self.QuestService = nil
    self.EnemyService = nil
    self.MovementService = nil
    self.CombatService = nil
    self.CombatDependencyAttempted = false
    self.CombatDependencyError = nil
    self.LastQuestAttemptKey = nil
    self.LastQuestAttemptAt = 0
    self.QuestStartAttemptCount = 0
    self.TimedOutQuestKey = nil
    self.QuestTimeoutReason = nil
    self.QuestDeferredForDialogue = false
    self.QuestDialogueRecovery = nil
    self.PendingQuestTargetName = nil
    self.LastQuestStateReason = nil
    self.QuestDiagnosticWaitKey = nil
    self.QuestDiagnosticWaitStartedAt = nil
    self.QuestDiagnosticReport = nil
    self.LastQuestDiagnosticSignature = nil
    self.LastQuestDiagnosticAt = 0
    self.SpawnCandidateDiagnostic = nil
    self.LastSpawnDiagnosticSignature = nil
    self.LastStatus = nil
    self.SpawnSearchTarget = nil
    self.SpawnCandidate = nil
    self.SpawnLoading = nil
    self.SpawnRetryAt = nil
    self.NextSpawnSearchAt = 0
    self.NextEnemySearchAt = 0

    local player = context.Compatibility.Player
    if player then
        self.CharacterAddedConnection = player.CharacterAdded:Connect(function()
            if self.MovementService then
                self.MovementService:Cancel()
            end
            if self.EnemyService then
                self.EnemyService:RestoreTargetCollision()
            end
            if self.CombatService then
                self.CombatService:Cancel()
            end
            self.Target = nil
            self.TargetName = nil
            self.Character = nil
            self.QuestDialogueRecovery = nil
            self:_ResetSpawnSearch(nil)
            self:_SetStatus("Character changed; farm session will reacquire after respawn", "warning")
        end)
        self.CharacterRemovingConnection = player.CharacterRemoving:Connect(function()
            if self.MovementService then
                self.MovementService:Cancel()
            end
            if self.CombatService then
                self.CombatService:Cancel()
            end
            self.QuestDialogueRecovery = nil
            self:_ClearTarget()
            self:_ResetSpawnSearch(nil)
        end)
    end
    return true
end

function MainFarm:Start()
    if self.Running then
        return true
    end
    local ready, setupError = self:_EnsureBaseServices()
    if not ready then
        self:_SetStatus("Main Farm unavailable: " .. tostring(setupError), "error")
        return false, setupError
    end

    self.Session += 1
    local collisionReady, collisionError = self.MovementService:SetFarmCollisionSuppression(true)
    if not collisionReady then
        self:_SetStatus("Main Farm collision setup failed: " .. tostring(collisionError), "error")
        return false, collisionError
    end
    self.Running = true
    self.CombatDependencyAttempted = false
    self.CombatDependencyError = nil
    self.LastQuestAttemptKey = nil
    self.LastQuestAttemptAt = 0
    self.TimedOutQuestKey = nil
    self.QuestTimeoutReason = nil
    self.QuestDeferredForDialogue = false
    self.QuestDialogueRecovery = nil
    self.PendingQuestTargetName = nil
    self.PendingQuestKey = nil
    self.PendingQuestReachedAt = nil
    self:_ResetSpawnSearch(nil)
    local session = self.Session
    self.Context.State:SetFeatureEnabled("farm.main", true)
    self:_SetStatus("Main Farm enabled; reading available quest state", "success")
    task.spawn(self._Run, self, session)
    return true
end

function MainFarm:Stop()
    self.Session += 1
    self.Running = false
    self:_EndQuestDiagnosticWait("stopped_before_confirmation", os.clock())
    if self.MovementService then
        self.MovementService:Cancel()
        self.MovementService:SetFarmCollisionSuppression(false)
    end
    if self.CombatService then
        self.CombatService:Cancel()
    end
    if self.EnemyService then
        self.EnemyService:RestoreTargetCollision()
        self.EnemyService:ClearIgnoredSpawns()
    end
    self.Target = nil
    self.TargetName = nil
    self.PendingQuestKey = nil
    self.PendingQuestReachedAt = nil
    self.PendingQuestTargetName = nil
    self.LastQuestAttemptKey = nil
    self.LastQuestAttemptAt = 0
    self.QuestStartAttemptCount = 0
    self.TimedOutQuestKey = nil
    self.QuestTimeoutReason = nil
    self.QuestDeferredForDialogue = false
    self.QuestDialogueRecovery = nil
    self.LastQuestStateReason = nil
    self:_ResetSpawnSearch(nil)
    self.QuestDiagnosticWaitKey = nil
    self.QuestDiagnosticWaitStartedAt = nil
    if self.Context and self.Context.State then
        self.Context.State:SetFeatureEnabled("farm.main", false)
    end
end

function MainFarm:Handle(actionId, payload)
    if actionId == "farm.status.copy" then
        return self:CopyStatusReport()
    end
    if actionId ~= "farm.main" then
        return false
    end
    if payload == true then
        self:Start()
    else
        self:Stop()
        self:_SetStatus("Main Farm stopped; movement and attack loop cancelled", "info")
    end
    return true
end

function MainFarm:Cleanup()
    self:Stop()
    if self.CharacterAddedConnection then
        self.CharacterAddedConnection:Disconnect()
        self.CharacterAddedConnection = nil
    end
    if self.CharacterRemovingConnection then
        self.CharacterRemovingConnection:Disconnect()
        self.CharacterRemovingConnection = nil
    end
    self.QuestService = nil
    self.EnemyService = nil
    self.MovementService = nil
    self.CombatService = nil
    self.Context = nil
    return true
end

return MainFarm
-- END SOURCE: src/ReplicatedStorage/CustomHub/Features/MainFarm.lua
end

__bundleFactories["CustomHub"] = function()
-- BEGIN SOURCE: src/ReplicatedStorage/CustomHub/init.lua
local Config = __bundleLoad("CustomHub.Config")
local State = __bundleLoad("CustomHub.State")
local Compatibility = __bundleLoad("CustomHub.Compatibility")
local FeatureManager = __bundleLoad("CustomHub.FeatureManager")
local UI = __bundleLoad("CustomHub.UI")

local Hub = {}
Hub.__index = Hub
local activeHub = nil

function Hub.new()
    local state = State.new(Config.Defaults)
    local compatibility = Compatibility.new()
    local featureManager = FeatureManager.new(state, compatibility, Config)

    return setmetatable({
        State = state,
        Compatibility = compatibility,
        FeatureManager = featureManager,
        UI = nil,
        Started = false,
        Destroying = false,
    }, Hub)
end

function Hub:Start()
    if self.Started then
        return true
    end

    local playerGui, playerGuiError = self.Compatibility:GetPlayerGui()
    if not playerGui then
        self.State:SetStatus(playerGuiError, "error")
        return false, playerGuiError
    end

    if activeHub and activeHub ~= self then
        activeHub:Destroy()
    end

    local initialized, initError = self.FeatureManager:Initialize()
    if not initialized then
        self.State:SetStatus("Feature setup error: " .. tostring(initError), "error")
        return false, initError
    end

    self.UI = UI.new(
        playerGui,
        self.State,
        self.Compatibility,
        Config,
        function(actionId, payload)
            return self.FeatureManager:Dispatch(actionId, payload)
        end,
        function()
            self:Destroy()
        end
    )

    local mounted, mountError = pcall(function()
        self.UI:Mount()
    end)
    if not mounted then
        self.UI:Destroy()
        self.UI = nil
        self.FeatureManager:Cleanup()
        self.State:SetStatus("UI mount error: " .. tostring(mountError), "error")
        return false, tostring(mountError)
    end

    self.Started = true
    activeHub = self
    self.State:SetStatus("Hub UI ready; Main Farm is available but disabled.", "success")
    return true
end

function Hub:Destroy()
    if self.Destroying then
        return
    end
    self.Destroying = true

    if self.UI then
        self.UI:Destroy()
        self.UI = nil
    end
    self.FeatureManager:Cleanup()
    self.Started = false
    if activeHub == self then
        activeHub = nil
    end
    self.State:SetStatus("Hub UI closed; feature cleanup completed.", "info")
    self.Destroying = false
end

return Hub
-- END SOURCE: src/ReplicatedStorage/CustomHub/init.lua
end

-- BEGIN BUNDLED CLIENT ENTRYPOINT
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local CustomHub = __bundleLoad("CustomHub")

local hub = CustomHub.new()
local started, startError = hub:Start()
if not started then
    warn("[CustomHub] " .. tostring(startError))
end

script.Destroying:Connect(function()
    hub:Destroy()
end)
-- END BUNDLED CLIENT ENTRYPOINT
